ce",{Text="Screen effect",Values={"Off","Rain","Snow"},Default="Rain",Callback=function(value)ambience:SetMode(value)end,})atmosphere:AddSlider("YSL_AmbienceIntensity",{Text="Rain / snow intensity",Default=36,Min=12,Max=48,Rounding=0,Callback=function(value)ambience:SetIntensity(value)end,})local themesGroup=tab:AddLeftGroupbox("Themes")local themeNames={}local defaultTheme=context.StartupTheme if not defaultTheme then defaultTheme="Aero"end for name in pairs(themes)do table.insert(themeNames,name)end table.sort(themeNames)themesGroup:AddDropdown("Wiggins_Theme",{Text="Theme list",Tooltip="Choose a color theme. Transparent also adds translucency to the UI surfaces.",Values=themeNames,Default=defaultTheme,Searchable=true,Callback=function(name)if themes[name]then outlineGradientEnabled=true applyTheme(context.Library,themes[name],name)updateOutlineGradient()end end,})themesGroup:AddButton("Set theme as default",function()local themeName=aztup_options.Wiggins_Theme.Value if not themeName then context.SetStatus("select a theme first")return end local ok,err=context.Config:SetDefaultTheme(themeName)context.SetStatus(ok and("default theme: "..themeName)or err)end)themesGroup:AddInput("Wiggins_CustomThemeName",{Text="Custom theme name",Default="My theme",Finished=true,})themesGroup:AddButton("Save custom theme",function()local name=aztup_options.Wiggins_CustomThemeName.Value if name==""then context.SetStatus("enter a theme name")return end local colors={}for _,key in ipairs({"FontColor","MainColor","AccentColor","BackgroundColor","OutlineColor"})do colors[key]=context.Library[key]end customThemes[name]=colors context.SetStatus("saved theme "..name)end)themesGroup:AddDropdown("Wiggins_CustomThemeList",{Text="Custom themes",Values={},AllowNull=true,Searchable=true,})themesGroup:AddButton("Refresh custom themes",function()local names={}for name in pairs(customThemes)do table.insert(names,name)end table.sort(names)aztup_options.Wiggins_CustomThemeList:SetValues(names)context.