hitbox=action.hitbox secondAction.name="(2)".." "..action.name self:action(timing,secondAction)end return self:action(timing,action)end end,["WeaponTest"]=function()local Action=getfenv().Action local Weapon=getfenv().Weapon local Signal=getfenv().Signal local Configuration=getfenv().Configuration local RepeatInfo=getfenv().RepeatInfo local Latency=getfenv().Latency local TaskSpawner=getfenv().TaskSpawner local ProjectileTracker=getfenv().ProjectileTracker local PartTiming=getfenv().PartTiming local Defense=getfenv().Defense return function(self,timing)if self.entity.Name:match("evengarde")and(timing.name:match("1SwordSwing1")or timing.name:match("1SwordSwing2"))then if _G.EvengardeSwingGuard and(os.clock()-_G.EvengardeSwingGuard)<4 then return end _G.EvengardeSwingGuard=os.clock()timing.ndfb=true timing.pbfb=true timing.bfht=0.15 TaskSpawner.spawn("EvengardeSwingParry",function()task.wait(0.4)local startTime=os.clock()while(os.clock()-startTime)<3 do local action=Action.new()action._when=0 action._type="Parry"action.hitbox=Vector3.new(55,55,55)action.name="Evengarde Sword Swing"self:action(timing,action)task.wait(0.01)end end)return end local data=Weapon.data(self.entity)if not data then return end local humanoidRootPart=self.entity:FindFirstChild("HumanoidRootPart")if not humanoidRootPart then return end timing.htype=Enum.PartType.Ball timing.fhb=false timing.hso=-5 timing.nvfb=true timing.pbfb=false timing.ndfb=false timing.bfht=0.3 timing.dp=false timing.pfh=true timing.phd=true timing.pfht=0.25 timing.phds=0.6 if data.type=="Fist"or data.type=="Dagger"then timing.phd=false timing.duih=false timing.ffh=true timing.pfht=0.5 timing.dp=false end if data.type=="Sword"or data.type=="Staff"or data.type=="Twinblade"or data.type=="Spear"or data.type=="Club"or data.type=="Rifle"or data.type=="Pistol"then timing.pbfb=true timing.bfht=0.3 timing.phd=false timing.duih=false timing.ffh=true timing.pfht=0.7 end if data.type=="Greathammer"or data.type=="Greatcannon"or data.type=="Greatsword"or data.type=="Greataxe"then timing.phd=false timing.duih=false timing.ffh=true timing.pfht=0.5 timing.dp=false end local windup=nil local hitbox=nil local ispeed=self.track.Speed if data.type=="Greataxe"and self.track.Speed~=1.0 then windup=(0.171/self.track.Speed)+0.120 elseif data.type=="Greataxe"and self.track.Speed==1.0 then windup=(0.171/self.track.Speed)windup+=0.250/data.ss elseif data.type=="Greathammer"and self.track.Speed~=1.0 then windup=(0.150/self.track.Speed)+0.200 elseif data.type=="Greathammer"and self.track.Speed==1.0 then windup=(0.150/self.track.Speed)windup+=0.250/data.ss elseif data.type=="Greatcannon"and self.track.Speed~=1.0 then windup=(0.155/self.track.Speed)+0.160 elseif data.type=="Greatcannon"and self.track.Speed==1.0 then windup=(0.155/self.track.Speed)+0.300 elseif data.type=="Rapier"then windup=(0.155/self.track.Speed)+0.120 elseif data.type=="Bow"then local thrown_object=workspace.Thrown:FindFirstChild("Attach_"..self.entity.Name)local tip_attachment=thrown_object and thrown_object:FindFirstChild("HandWeapon")and thrown_object:FindFirstChild("HandWeapon"):FindFirstChild("TipAttachment")if tip_attachment then local ready=false while task.wait()and self.track.IsPlaying do ready=tip_attachment:FindFirstChild("Spark")if ready then break end end if not ready then return end end windup=0.1 elseif data.type=="Pistol"and not timing.name:match("Shot")then windup=0.350/data.ss elseif data.type=="Pistol"and timing.name:match("Shot")then repeat task.wait()until self.track.Speed~=ispeed windup=0.075/self.track.Speed if self.track.Speed==0.0 then windup=0.100 end elseif data.type=="Rifle"and timing.name:match("2")then repeat task.wait()until self.track.Speed~=ispeed windup=(0.150/self.track.Speed)if self.track.Speed==0.0 then windup=0.100 end elseif data.type=="Rifle"then windup=(0.174/self.track.Speed)+0.125 elseif data.type=="Club"then windup=(0.180/self.track.Speed)+0.100 elseif data.type=="Twinblade"then windup=(0.200/self.track.Speed)+0.050 elseif data.type=="Spear"then windup=(0.150/self.track.Speed)+0.100 elseif data.type=="Greatsword"then windup=(0.158/self.track.Speed)+0.150 elseif data.type=="Fist"then windup=(0.140/self.track.Speed)+0.130 elseif data.type=="Dagger"then windup=(0.200/self.track.Speed)+0.075 elseif data.type=="Staff"then windup=0.350 elseif data.type=="Sword"then windup=(0.200/self.track.Speed)+0.100 end if self.entity.Name:lower():match("titus")and data.type=="Fist"then repeat task.wait()until self.track.Speed>0 local finalSpeed=self.track.Speed+0.2 self:notify(timing,"Titus M1 Windup")local action=Action.new()action._when=(565*0.76)/finalSpeed action._type="Parry"action.hitbox=Vector3.new(data.length*2.1,data.length*2.1,data.length*2.1)action.name=string.format("(%.2f) Titus M1 Windup",finalSpeed)return self:action(timing,action)end if not windup then return self:notify(timing,"(%s) No windup for this weapon type.",data.type)end local action=Action.new()action._when=windup*1000 action._type="Parry"action.hitbox=hitbox or Vector3.new(data.length*2.1,data.length*2.1,data.length*2.1)action.name=string.format("(%.2f, %.2f, %.2f) (%.2f) Dynamic Weapon Swing",data.oss,data.ss,self.track.Speed,data.length)if data.type=="Pistol"then TaskSpawner.spawn("WeaponTest_ScrapsingerBullet",function()local thrown=workspace:FindFirstChild("Thrown")if not thrown then return end local tracker=ProjectileTracker.new(function(candidate)return candidate.Name=="ScrapsingerBullet_"..self.entity.Name end)local bulletAction=Action.new()bulletAction._when=0 bulletAction._type="Parry"bulletAction.name="Scrapsinger Bullet"local pt=PartTiming.new()pt.uhc=true pt.duih=true pt.fhb=true pt.name="ScrapsingerBulletProjectile"pt.hitbox=Vector3.new(20,35,15)pt.actions:push(bulletAction)pt.cbm=true Defense.cdpo(tracker:wait(),pt)end)end return self:action(timing,action)end end,["WeaponUppercutTest"]=function()local Action=getfenv().Action local Weapon=getfenv().Weapon return function(self,timing)local data=Weapon.data(self.entity)if not data then return end timing.ffh=true timing.phd=true timing.nvfb=true timing.pfht=0.25 timing.phds=1.0 local windup=nil if data.type=="Dagger"then windup=(0.166/self.track.Speed)+0.120 elseif data.type=="Greataxe"then windup=(0.141/self.track.Speed)+0.100 elseif data.type=="Greathammer"then windup=(0.150/self.track.Speed)+0.100 elseif data.type=="Greatsword"then windup=(0.157/self.track.Speed)+0.100 elseif data.type=="Greatcannon"then windup=(0.166/self.track.Speed)+0.100 elseif data.type=="Twinblade"then windup=(0.163/self.track.Speed)+0.130 elseif data.type=="Bow"then windup=(0.150/self.track.Speed)+0.140 elseif data.type=="Club"then windup=(0.166/self.track.Speed)+0.140 elseif data.type=="Pistol"then repeat task.wait()until self.track.Speed>=0.1 windup=(0.166/self.track.Speed)+0.150 elseif data.type=="Rifle"then windup=(0.159/self.track.Speed)+0.140 elseif data.type=="Rapier"then windup=(0.181/self.track.Speed)+0.130 elseif data.type=="Fist"then windup=(0.150/self.track.Speed)+0.120 elseif data.type=="Sword"or data.type=="Staff"then windup=(0.150/self.track.Speed)+0.100 elseif data.type=="Spear"then windup=(0.163/self.track.Speed)+0.100 windup+=0.050/data.ss end if not windup then return self:notify(timing,"(%s) No windup for this weapon type.",data.type)end local action=Action.new()action._when=windup*1000 action._type="Parry"action.hitbox=Vector3.new(data.length*2,data.length*2,data.length*2.2)action.name=string.format("(%.2f, %.2f, %.2f) (%.2f) Dynamic Weapon Upper",data.oss,data.ss,self.track.Speed,data.length)return self:action(timing,action)end end,["WhalingCrit"]=function()local Action=getfenv().Action return function(self,timing)local distance=self:distance(self.entity)local action=Action.new()action._when=math.min(300+distance*6.5)action._type="Parry"action.hitbox=Vector3.new(17,10,18)action.name=string.format("(%.2f) Dynamic Whaling Crit Timing",distance)return self:action(timing,action)end end,["WindBlade"]=function()local PartTiming=getfenv().PartTiming local Action=getfenv().Action local ProjectileTracker=getfenv().ProjectileTracker local Defense=getfenv().Defense local Latency=getfenv().Latency return function(self,timing)local thrown=workspace:FindFirstChild("Thrown")if not thrown then return end local tracker=ProjectileTracker.new(function(candidate)return candidate.Name=="WindSlashProjectile"end)task.wait(0.5-Latency.rtt())if self:distance(self.entity)<=20 then local action=Action.new()action._type="Parry"action._when=0 action.name="Arc Beam Close Timing"action.ihbc=true return self:action(timing,action)end local action=Action.new()action._when=0 action._type="Parry"action.name="Wind Slash Part"local pt=PartTiming.new()pt.uhc=true pt.duih=true pt.fhb=true pt.name="WindSlashProjectile"pt.hitbox=Vector3.new(10,10,10)pt.actions:push(action)pt.cbm=true Defense.cdpo(tracker:wait(),pt)end end,["WindCarve"]=function()local Action=getfenv().Action local Mantra=getfenv().Mantra local Signal=getfenv().Signal return function(self,timing)local data=Mantra.data(self.entity,"Mantra:CarveWind{{Wind Carve}}")local range=data.stratus*1.4+data.cloud*0.9 timing.ffh=true timing.pfh=true timing.fhb=true timing.rpue=false timing.duih=true timing.hitbox=Vector3.new(20+range,20+range,20+range)local action=Action.new()action._when=400 action._type="Start Block"action.name="Wind Carve Start"self:action(timing,action)local hrp=self.entity:FindFirstChild("HumanoidRootPart")if not hrp then return end local onDescendantAdded=Signal.new(self.entity.DescendantAdded)self.tmaid:add(onDescendantAdded:connect("WindCarve_StopCarve",function(child)if child.Name=="StopCarve"then local actionTwo=Action.new()actionTwo._when=0 actionTwo._type="End Block"actionTwo.ihbc=true actionTwo.name="Wind Carve End"self:action(timing,actionTwo)end end))end end,["WindGun"]=function()local Action=getfenv().Action return function(self,timing)timing.ffh=true local distance=self:distance(self.entity)local action=Action.new()action._w