ocal csc=rs and string.match(rs,"(%d+)%s*[xX]%s*Cloudstone")local gsc=rs and string.match(rs,"(%d+)%s*[xX]%s*Glass Stone")local msc=rs and string.match(rs,"(%d+)%s*[xX]%s*Magnifying Stone")return{blast=bsp and true or false,spring=ssp and true or false,tornado=tsp and true or false,drift=dsc and tonumber(dsc)or 0,rush=rsc and tonumber(rsc)or 0,perfect=plc and tonumber(plc)or 0,crystal=clc and tonumber(clc)or 0,stratus=stc and tonumber(stc)or 0,cloud=csc and tonumber(csc)or 0,glass=gsc and tonumber(gsc)or 0,magnifying=msc and tonumber(msc)or 0,}end return Mantra end,["ProjectileListener"]=function()local Maid=getfenv().Maid local Signal=getfenv().Signal local Logger=getfenv().Logger local ProjectileListener={}ProjectileListener.__index=ProjectileListener local trackerObjects={}function ProjectileListener.detach()for _,trackerObject in next,trackerObjects do if not trackerObject.maid then continue end trackerObject.maid:clean()end end function ProjectileListener:connect(callback)local thrown=workspace:WaitForChild("Thrown")local childAdded=Signal.new(thrown.ChildAdded)self.maid:clean()self.maid:mark(childAdded:connect(string.format("%s_ProjectileListener_ThrownChildAdded",self.identifier),callback))end function ProjectileListener.new(identifier)local self=setmetatable({},ProjectileListener)self.maid=Maid.new()self.identifier=identifier trackerObjects[#trackerObjects+1]=self return self end return ProjectileListener end,["ProjectileTracker"]=function()local Signal=getfenv().Signal local Maid=getfenv().Maid local ProjectileTracker={}ProjectileTracker.__index=ProjectileTracker local seenProjectiles={}local trackerObjects={}local ptMaid=Maid.new()local thrown=workspace:WaitForChild("Thrown")local childAdded=Signal.new(thrown.ChildAdded)ptMaid:mark(childAdded:connect("ProjectileTracker_ThrownChildAdded",function(child)for _,tracker in next,trackerObjects do if tracker.projectile then continue end if not tracker.callback(child)then continue end if seenProjectiles[child]then