	action._when = (2130 * 1.21) / self.track.Speed
	action._type = "Parry"
	action.hitbox = Vector3.new(100, 250, 100)
	action.name = string.format("(%.2f) Dynamic Primadon Timing", self.track.Speed)
	return self:action(timing, action)
end

]],["ElectroCarve"]=[[
---@class Action
local Action = getfenv().Action

---@class RepeatInfo
local RepeatInfo = getfenv().RepeatInfo

---@module Game.Latency
local Latency = getfenv().Latency

---@class Signal
local Signal = getfenv().Signal

---Module function.
---@param self AnimatorDefender
---@param timing AnimationTiming
return function(self, timing)
	timing.ffh = true
	timing.fhb = true
	timing.rpue = false
	timing.duih = true
	timing._rpd = 150
	timing._rsd = 300
	timing.hitbox = Vector3.new(20, 14, 16)

	local stopped = false

	self:hook("rc", function()
		return stopped
	end)

	local info = RepeatInfo.new(timing, Latency.rdelay(), self:uid(10))
	info.track = self.track
	self:srpue(self.entity, timing, info)

	local hrp = self.entity:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return
	end

	local humanoid = self.entity:FindFirstChildOfClass("Humanoid")
	if not humanoid then
		return
	end

	stopped = true

	repeat
		task.wait()
	until not self.track.IsPlaying

	task.wait(0.3)

	stopped = false
end

