]],["ShadowSaintsworn"]=[[
---@type PartTiming
local PartTiming = getfenv().PartTiming

---@type Action
local Action = getfenv().Action

---@type ProjectileTracker
local ProjectileTracker = getfenv().ProjectileTracker

---@module Features.Combat.Defense
local Defense = getfenv().Defense

---@module Game.Latency
local Latency = getfenv().Latency

---Module function.
---@param self AnimatorDefender
---@param timing AnimationTiming
return function(self, timing)
	local thrown = workspace:FindFirstChild("Thrown")
	if not thrown then
		return
	end

	local tracker = ProjectileTracker.new(function(candidate)
		return candidate.Name == "ShadowSlash"
	end)

	task.wait(math.max(0, 0.5 - Latency.rtt()))

	if self:distance(self.entity) <= 20 then
		local action = Action.new()
		action._type = "Parry"
		action._when = 100
		action.name = "Shadow SlashClose"
		action.ihbc = true
		action.fhb = true
		return self:action(timing, action)
	end

	local action = Action.new()
	action._when = 0
	action._type = "Parry"
	action.name = "Shadow Slash Part"

	local pt = PartTiming.new()
	pt.uhc = true
	pt.duih = true
	pt.fhb = true
	pt.name = "ShadowSlash"
	pt.hitbox = Vector3.new(30, 25, 30)
    pt.hso = 15
	pt.actions:push(action)
	pt.cbm = true

	Defense.cdpo(tracker:wait(), pt)
end

]],["ShadowSludge"]=[[
---@class Action
local Action = getfenv().Action

---@class Signal
local Signal = getfenv().Signal

---@class Maid
local Maid = getfenv().Maid

---@class TerrainListener
local TerrainListener = getfenv().TerrainListener

-- Listener object.
local tlistener = TerrainListener.new("ShadowSludge")

---Module function.
---@param self EffectDefender
---@param timing EffectTiming
return function(self, timing)
	if self:distance(self.owner) >= 50 then
		return
	end

	local humanoidRootPart = self.owner:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return
	end

	local terrain = workspace:FindFirstChild("Terrain")
	if not terrain then
		return
	end

	tlistener:connect(function(child)
		if child.Name ~= "REP_EMIT" then
			return
		end

		if not child:IsA("Attachment") then
			return
		end

		task.wait(0.02)

		if (child.Position - humanoidRootPart.Position).Magnitude >= 5 then
			return
		end

		if self:distance(self.owner) >= 50 then
			return
		end

		timing.fhb = false

		local action = Action.new()
		action._when = 0
		action._type = "Parry"
		action.ihbc = true
		action.name = "Dynamic Shadow Sludge Timing"
		self:action(timing, action)
	end)
end

