]],["SharkoKick"]=[[
---@class Action
local Action = getfenv().Action

---@module Game.Latency
local Latency = getfenv().Latency

---Module function.
---@param self AnimatorDefender
---@param timing AnimationTiming
return function(self, timing)
	if not self.entity.Name:match("mecha") then
		local action = Action.new()
		action._when = 530
		action._type = "Dodge"
		action.hitbox = Vector3.new(25, 70, 25)
		action.name = "Normal Kick Timing"
		return self:action(timing, action)
	end

	local action = Action.new()
	action._when = 0
	action._type = "Dodge"
	action.hitbox = Vector3.new(25, 70, 25)
	action.name = "Normal Kick Timing"

	local lastTimestamp = os.clock()

	while task.wait() do
		if (os.clock() - lastTimestamp) > (0.6 - Latency.rtt()) then
			break
		end

		if self.track.TimePosition < 0.2 or self.track.Speed ~= 0 then
			continue
		end

		action._when = 280
		action._type = "Dodge"
	end

	return self:action(timing, action)
end

]],["ShoulderBash"]=[[
---@class Action
local Action = getfenv().Action

---@module Modules.Globals.Waiter
local Waiter = getfenv().Waiter

---@class Timing
local Timing = getfenv().Timing

---@module Game.Latency
local Latency = getfenv().Latency

---Module function.
---@param self AnimatorDefender
---@param timing AnimationTiming
return function(self, timing)
	local humanoid = self.entity:FindFirstChild("Humanoid")
	if not humanoid then
		return
	end

	local animator = humanoid:FindFirstChild("Animator")
	if not animator then
		return
	end

	task.wait(0.35 - Latency.rtt())

	if self:distance(self.entity) <= 10 then
		local firstTiming = Timing.new()
		firstTiming.fhb = true
		firstTiming.duih = false
		firstTiming.rpue = false
		firstTiming.name = "ShoulderBashWindup"
		firstTiming.cbm = true

		local action = Action.new()
		action._when = 0
		action._type = "Parry"
		action.ihbc = true
		action.name = "Shoulder Bash Close"
		return self:action(firstTiming, action)
	end

	local track = Waiter.fet("rbxassetid://9400896040", animator)
	if not track then
		return
	end

	timing.fhb = true
	timing.duih = true
	timing.rpue = false
	timing.hitbox = Vector3.new(15, 15, 20)

	self:hook("stopped", function(...)
		return not track.IsPlaying
	end)

	local action = Action.new()
	action._when = 0
	action._type = "Parry"
	action.hitbox = Vector3.new(10, 10, 20)
	action.name = "Shoulder Bash Far"
	self:action(timing, action)
end


