m",function(require,_LOADED,__bundle_register,__bundle_modules)local Filesystem=require("Utility/Filesystem")local JSON=require("Utility/JSON")local CustomAPI=require("Features/Custom/CustomAPI")local Logger=require("Utility/Logger")local Custom={}local storage=Filesystem.new("Aero/Custom")local host=nil local running={}local settingsCache=nil local DEFAULT_SETTINGS={provider="OpenAI",model="gpt-4o-mini",apiKey="",autorun={},}Custom.PROVIDERS={"OpenAI","Anthropic","Google"}Custom.DEFAULT_MODELS={OpenAI="gpt-4o-mini",Anthropic="claude-3-5-sonnet-latest",Google="gemini-1.5-flash",}Custom.TEMPLATE=table.concat({"-- Custom feature. The Aero API is available as globals (and under `Aero`).","-- Widgets appear in a section on the right; everything is cleaned up on reload.","",'local enabled = Toggle("Enabled", function(on)','    Notify(on and "Enabled" or "Disabled")',"end)","",'Slider("Speed", { min = 16, max = 200, default = 16, callback = function(v)',"    local hum = Humanoid()","    if hum then hum.WalkSpeed = v end","end })","","OnRender(function()","    if not enabled.get() then return end","    -- runs every frame while this feature is loaded","end)",},"\n")function Custom.settings()if settingsCache then return settingsCache end local data=nil pcall(function()if storage:file("settings.json")then local ok,decoded=pcall(JSON.decode,storage:read("settings.json"))if ok and type(decoded)=="table"then data=decoded end end end)data=data or{}for k,v in pairs(DEFAULT_SETTINGS)do if data[k]==nil then data[k]=v end end if type(data.autorun)~="table"then data.autorun={}end settingsCache=data return data end function Custom.saveSettings()local s=Custom.settings()pcall(function()storage:write("settings.json",JSON.encode(s))end)end function Custom.setSetting(key,value)local s=Custom.settings()s[key]=value Custom.saveSettings()end function Custom.list()local out={}pcall(function()for _,filename in ipairs(storage:list())do if type(filename)=="string"and filename:sub(-4)==".lua"then out[#out+1]=filename:sub(1,#filename-4)end end end)table.sort(out)return out end function Custom.load(name)local source pcall(function()if storage:file(name..".lua")then source=storage:read(name..".lua")end end)return source end function Custom.save(name,source)if type(name)~="string"or name:gsub("%s","")==""then return false,"invalid name"end name=name:gsub("[\\/:*?\"<>|]","_")local ok,err=pcall(function()storage:write(name..".lua",source or"")end)if not ok then return false,tostring(err)end return true end function Custom.delete(name)Custom.stop(name)pcall(function()if storage:file(name..".lua")then storage:delete(name..".lua")end end)local s=Custom.settings()if s.autorun[name]then s.autorun[name]=nil Custom.saveSettings()end end function Custom.setHost(panel)host=panel end function Custom.isRunning(name)return running[name]~=nil end function Custom.runningNames()local out={}for name in pairs(running)do out[#out+1]=name end table.sort(out)return out end function Custom.stop(name)local inst=running[name]if inst then pcall(inst.destroy)running[name]=nil end end function Custom.stopAll()for name in pairs(running)do Custom.stop(name)end end function Custom.run(name,source)if not host then return false,"custom panel not ready"end Custom.stop(name)local chunk,compileErr=loadstring(source)if not chunk then local clean=tostring(compileErr):gsub('^%[string "[^"]*"%]:',"line ")return false,"syntax: "..clean end local inst=CustomAPI.new(host,name)pcall(setfenv,chunk,inst.env)local ranOk,runErr=pcall(chunk)if not ranOk then pcall(inst.destroy)local clean=tostring(runErr):gsub('^%[string "[^"]*"%]:',"line ")return false,"runtime: "..clean end running[name]=inst return true end function Custom.setAutorun(name,on)local s=Custom.settings()s.autorun[name]=on and true or nil Custom.saveSettings()end function Custom.isAutorun(name)return Custom.settings().autorun[name]==true end function Custom.autorunAll()local s=Custom.settings()for name in pairs(s.autorun)do local source=Custom.load(name)if source then local ok,err=Custom.run(name,source)if not ok then Logger.notify("[Custom] autorun '%s' failed: %s",tostring(name),tostring(err))end end end end local function httpRequest()return(syn and syn.request)or(http and http.request)or http_request or request or(getgenv and getgenv().request)end local API_REFERENCE=table.concat({"You write Luau code for the Roblox game Deepwoken, run inside the 'Aero' exploit menu's custom-feature sandbox.","The following API is available as GLOBAL functions (also under the `Aero` table). Use ONLY this API for UI + lifecycle:","","UI (each returns a control object):","  Toggle(text, function(value) end)  -- or Toggle(text, { default=bool, callback=fn }); control.get()/control.set(v)","  Button(text, function() end)","  Slider(text, { min=number, max=number, default=number, decimals=number, callback=function(value) end }); control.get()/set(v)","  Dropdown(text, { values={...}, default=any, callback=function(value) end }); control.get()/set(v)/setValues(t)","  Input(text, { default=string, callback=function(text) end }); control.get()/set(v)","  Keybind(text, { default='E', callback=function(key) end })  -- fires callback when the bound key is pressed","  Label(text); control.set(text)","  Section(title) -> a sub-surface with the same UI methods","  Window(title) -> a floating draggable window, a sub-surface with the same UI methods","","Lifecycle (auto-cleaned on reload):","  OnRender(function(dt) end)   -- every RenderStepped frame","  OnStep(function(dt) end)     -- every Heartbeat","  OnInput(function(input, gameProcessed) end)","  Interval(seconds, function() end)","  OnCleanup(function() end)","  Notify(text, seconds)","","Game helpers:","  LocalPlayer, Character(), HRP(), Humanoid(), Mouse(), Camera()","  GetTarget() -> { character, humanoid, root, du } (nearest aim target) ; GetTargets() -> list","  Value(flag) -> read an existing Aero toggle/option by flag; Toggles, Options, Services, Library","  Standard Roblox globals (game, workspace, task, math, Vector3, CFrame, etc.) are available.","","Rules: output ONLY runnable Luau code, no markdown fences, no explanation. Do not call loadstring/HttpGet/setfenv.","Guard every frame loop with a toggle. Keep it concise and correct.",},"\n")local function extractCode(text)if type(text)~="string"then return nil end local fenced=text:match("```[%w]*\n(.-)```")if fenced and fenced:gsub("%s","")~=""then return fenced end return text end function Custom.generate(prompt,cb)task.spawn(function()local s=Custom.settings()local req=httpRequest()if not req then return cb(false,"no HTTP request function on this executor")end if not s.apiKey or s.apiKey:gsub("%s","")==""then return cb(false,"set your API key first")end local provider=s.provider or"OpenAI"local model=(s.model and s.model:gsub("%s","")~=""and s.model)or Custom.DEFAULT_MODELS[provider]or"gpt-4o-mini"local url,headers,body if provider=="Anthropic"then url="https://api.anthropic.com/v1/messages"headers={["x-api-key"]=s.apiKey,["anthropic-version"]="2023-06-01",["Content-Type"]="application/json",}body=JSON.encode({model=model,max_tokens=2048,system=API_REFERENCE,messages={{role="user",content=prompt}},})elseif provider=="Google"then url="https://generativelanguage.googleapis.com/v1beta/models/"..model..":generateContent?key="..s.apiKey headers={["Content-Type"]="application/json"}body=JSON.encode({system_instruction={parts={{text=API_REFERENCE}}},contents={{role="user",parts={{text=prompt}}}},})else url="https://api.openai.com/v1/chat/completions"headers={["Authorization"]="Bearer "..s.apiKey,["Content-Type"]="application/json",}body=JSON.encode({model=model,temperature=0.4,messages={{role="system",content=API_REFERENCE},{role="user",content=prompt},},})end local ok,res=pcall(req,{Url=url,Method="POST",Headers=headers,Body=body,})if not ok or type(res)~="table"then return cb(false,"request failed: "..tostring(res))end local status=res.StatusCode or res.Status or 0 if type(res.Body)~="string"or res.Body==""then return cb(false,"empty response (status "..tostring(status)..")")end local decodeOk,decoded=pcall(JSON.decode,res.Body)if not decodeOk or type(decoded)~="table"then return cb(false,"bad JSON (status "..tostring(status)..")")end if decoded.error then local msg=type(decoded.error)=="table"and decoded.error.message or tostring(decoded.error)return cb(false,"api error: "..tostring(msg))end local content if provider=="Anthropic"then content=decoded.content and decoded.content[1]and decoded.content[1].text elseif provider=="Google"then content=decoded.candidates and decoded.candidates[1]and decoded.candidates[1].content and decoded.candidates[1].content.parts and decoded.candidates[1].content.parts[1]and decoded.candidates[1].content.parts[1].text else content=decoded.choices and decoded.choices[1]and decoded.choices[1].message and decoded.choices[1].message.content end if type(content)~="string"or content:gsub("%s","")==""then return cb(false,"no code in response (status "..tostring(status)..")")end return cb(true,extractCode(content))end)end return Custom end)__bundle_register("Features/Custom/CustomAPI",function(require,_LOADED,__bundle_register,__bundle_modules)local Library=require("GUI/Library")local Widgets=require("Features/Custom/CustomWidgets")local Configuration=require("Utility/Configuration")local Targeting=require("Features/Combat/Targeting")local Logger=require("Utility/Logger")local Players=game:GetService("Players")local RunService=game:GetService("RunService")local UserInputService=game:GetService("UserInputService")local Workspace=game:GetService("Workspace")local CustomAPI={}local function normalizeOpts(arg)if type(arg)=="function"then return{callback=arg}end if type(arg)=="table"then return arg end return{}end function CustomAPI.new(hostBody,name)local conns={}local roots={}local cleanupFns={}local intervals={}local destroyed=false local function track(control)if control and control.conns then for _,c in ipairs(control.conns)do conns[#conns+1]=c end end return control end local function trackConn(c)conns[#conns+1]=c return c end local rootSection=Widgets.section(hostBody,name or"Custom Feature")roots[#roots+1]=rootSection.instance local function buildSurface(parent)local surface={}function surface.Label(text)return track(Widgets.label(parent,text))end function surface.Button(text,callback)return track(Widgets.button(parent,text,callback))end function surface.Toggle(text,arg)local o=normalizeOpts(arg)return track(Widgets.toggle(parent,text,o.default,o.callback))end function surface.Slider(text,arg)local o=normalizeOpts(arg)return track(Widgets.slider(parent,text,o.min,o.max,o.default,o.callback,o.decimals))end function surface.Dropdown(text,arg)local o=normalizeOpts(arg)return track(Widgets.dropdown(parent,text,o.values,o.default,o.callback))end function surface.Input(text,arg)local o=normalizeOpts(arg)return track(Widgets.input(parent,text,o.default,o.callback))end function surface.Keybind(text,arg)local o=normalizeOpts(arg)return track(Widgets.keybind(parent,text,o.default,o.callback))end function surface.Section(title)local sec=track(Widgets.section(parent,title))return buildSurface(sec.body)end return surface end local root=buildSurface(rootSection.body)local function makeWindow(title)local gui=Library.ScreenGui local outer=Library:Create("Frame",{Name="CustomWindow",AnchorPoint=Vector2.new(0.5,0.5),Position=UDim2.fromScale(0.5,0.5),Size=UDim2.fromOffset(240,60),AutomaticSize=Enum.AutomaticSize.Y,BackgroundColor3=Library.MainColor,BorderSizePixel=0,ZIndex=70,Parent=gui,})Library:Create("UICorner",{CornerRadius=UDim.new(0,6),Parent=outer})local os=Library:Create("UIStroke",{Color=Library.AccentColor,Thickness=1,Transparency=0.2,Parent=outer})Library:AddToRegistry(outer,{BackgroundColor3="MainColor"})Library:AddToRegistry(os,{Color="AccentColor"})pcall(function()Library:AddUIScale(outer)end)local bar=Library:Create("TextLabel",{BackgroundColor3=Library.BackgroundColor,BorderSizePixel=0,Size=UDim2.new(1,0,0,24),Font=Enum.Font.GothamBold,Text="  "..tostring(title or"Window"),TextSize=13,TextColor3=Library.FontColor,TextXAlignment=Enum.TextXAlignment.Left,ZIndex=71,Parent=outer,})Library:Create("UICorner",{CornerRadius=UDim.new(0,6),Parent=bar})Library:AddToRegistry(bar,{BackgroundColor3="BackgroundColor",TextColor3="FontColor"})pcall(function()Library:MakeDraggable(outer,24)end)local body=Library:Create("Frame",{BackgroundTransparency=1,Position=UDim2.fromOffset(6,28),Size=UDim2.new(1,-12,0,0),AutomaticSize=Enum.AutomaticSize.Y,ZIndex=71,Parent=outer,})Library:Create("UIListLayout",{SortOrder=Enum.SortOrder.LayoutOrder,Padding=UDim.new(0,4),Parent=body})Library:Create("UIPadding",{PaddingBottom=UDim.new(0,6),Parent=body})roots[#roots+1]=outer return buildSurface(body)end local api={}for k,v in pairs(root)do api[k]=v end function api.Window(title)return makeWindow(title)end function api.OnRender(fn)trackConn(RunService.RenderStepped:Connect(function(dt)if not destroyed then local ok,err=pcall(fn,dt)if not ok then Logger.notify("[Custom] render error: %s",tostring(err))end end end))end function api.OnStep(fn)trackConn(RunService.Heartbeat:Connect(function(dt)if not destroyed then pcall(fn,dt)end end))end function api.OnInput(fn)trackConn(UserInputService.InputBegan:Connect(function(input,gameProcessed)if not destroyed then pcall(fn,input,gameProcessed)end end))end function api.Interval(seconds,fn)seconds=tonumber(seconds)or 1 local token={running=true}intervals[#intervals+1]=token task.spawn(function()while token.running and not destroyed do task.wait(seconds)if token.running and not destroyed then pcall(fn)end end end)end function api.OnCleanup(fn)cleanupFns[#cleanupFns+1]=fn end function api.Notify(text,time)pcall(function()Library:Notify(tostring(text),time)end)end api.LocalPlayer=Players.LocalPlayer api.Services={Players=Players,RunService=RunService,UserInputService=UserInputService,Workspace=Workspace,ReplicatedStorage=game:GetService("Rep