d(sel)if not source then return setStatus("Could not read '%s'.",sel)end if editor then editor.set(source)end Options.Custom_FeatureName:SetValue(sel)if Toggles.Custom_Autorun then Toggles.Custom_Autorun:SetValue(Custom.isAutorun(sel))end editorWindow:Show()setStatus("Loaded '%s'.",sel)end)manageBox:AddButton("New",function()if editor then editor.set(Custom.TEMPLATE)end Options.Custom_FeatureName:SetValue("")setStatus("New feature.")end):AddButton("Delete",function()local sel=Options.Custom_FeatureList.Value if type(sel)~="string"or sel==""then return setStatus("Select a feature to delete.")end Custom.delete(sel)refreshList()Options.Custom_FeatureList:SetValue(nil)setStatus("Deleted '%s'.",sel)end)local autorunToggle=manageBox:AddToggle("Custom_Autorun",{Text="Autorun this feature on load",Default=false,})autorunToggle:OnChanged(function(value)local name=currentName()if name then Custom.setAutorun(name,value)end end)statusLabel=manageBox:AddLabel("Idle.",true)local aiBox=tab:AddLeftGroupbox("AI Settings")local s=Custom.settings()aiBox:AddDropdown("Custom_AIProvider",{Text="Provider",Values=Custom.PROVIDERS,Default=s.provider})aiBox:AddInput("Custom_AIModel",{Text="Model",Default=s.model})aiBox:AddInput("Custom_AIKey",{Text="API key",Default=s.apiKey})local aiReady=false Options.Custom_AIProvider:OnChanged(function(value)Custom.setSetting("provider",value)if aiReady then local model=Custom.DEFAULT_MODELS[value]if model then Options.Custom_AIModel:SetValue(model)end end end)Options.Custom_AIModel:OnChanged(function(value)Custom.setSetting("model",value)end)Options.Custom_AIKey:OnChanged(function(value)Custom.setSetting("apiKey",value)end)aiReady=true aiBox:AddLabel("Key is stored locally (workspace/Aero/Custom), never in configs.",true)local controlsBox=tab:AddRightGroupbox("Custom Controls")local holder=Library:Create("Frame",{BackgroundColor3=Library.MainColor,BorderSizePixel=0,Size=UDim2.new(1,-4,0,360),LayoutOrder=9999,ZIndex=5,Parent=controlsBox.Container,})Library:Create("UICorner",{CornerRadius=UDim.new(0,4),Parent=holder})Library:AddToRegistry(holder,{BackgroundColor3="MainColor"})local hstroke=Library:Create("UIStroke",{Color=Library.OutlineColor,Thickness=1,Transparency=0.5,Parent=holder})Library:AddToRegistry(hstroke,{Color="OutlineColor"})local host=Library:Create("ScrollingFrame",{BackgroundTransparency=1,BorderSizePixel=0,Position=UDim2.fromOffset(6,6),Size=UDim2.new(1,-12,1,-12),CanvasSize=UDim2.new(0,0,0,0),AutomaticCanvasSize=Enum.AutomaticSize.Y,ScrollBarThickness=4,ZIndex=6,Parent=holder,})Library:Create("UIListLayout",{SortOrder=Enum.SortOrder.LayoutOrder,Padding=UDim.new(0,6),Parent=host})Library:Create("UIPadding",{PaddingRight=UDim.new(0,4),Parent=host})local emptyHint=Library:Create("TextLabel",{BackgroundTransparency=1,Size=UDim2.new(1,0,0,40),Font=Enum.Font.Gotham,Text="Run a feature to see its controls here.",TextSize=12,TextColor3=Library.OutlineColor,TextWrapped=true,Parent=host,})Library:AddToRegistry(emptyHint,{TextColor3="OutlineColor"},true)Custom.setHost(host)pcall(function()controlsBox:Resize()end)task.spawn(function()Custom.autorunAll()end)end return CustomTab end)__bundle_register("Features/Custom/AIChat",function(require,_LOADED,__bundle_register,__bundle_modules)local JSON=require("Utility/JSON")local GameTools=require("Features/Custom/GameTools")local Custom=require("Features/Custom/Custom")local AIChat={}local MAX_STEPS=10 AIChat.busy=false AIChat.lastCode=nil AIChat.messages=nil AIChat.current=nil function AIChat.cancel()if AIChat.current then AIChat.current.cancelled=true end end local function httpRequest()return(syn and syn.request)or(http and http.request)or http_request or request or(getgenv and getgenv().request)end local function systemPrompt()return table.concat({"You are an expert assistant embedded in 'Aero', a menu for the Roblox game Deepwoken. You help the","user understand the game and build custom features. You can inspect the LIVE game and decompile","scripts via tools before answering, so prefer checking real data over guessing.","",GameTools.API_REFERENCE,"",GameTools.TOOLS_DOC,"","Be concise. When the user asks for a feature, inspect what you need, then give the final code in a","single ```lua block using only the API above.",},"\n")end function AIChat.reset()AIChat.messages={{role="system",content=systemPrompt()}}AIChat.lastCode=nil end local function ensureInit()if not AIChat.messages then AIChat.reset()end end local function chatComplete(messages)local s=Custom.settings()local req=httpRequest()if not req then return false,"no HTTP request function on this executor"end if not s.apiKey or s.apiKey:gsub("%s","")==""then return false,"set your API key in the Custom tab first"end local provider=s.provider or"OpenAI"local model=(s.model and s.model:gsub("%s","")~=""and s.model)or Custom.DEFAULT_MODELS[provider]or"gpt-4o-mini"local url,headers,body if provider=="Anthropic"then local system={}local msgs={}for _,m in ipairs(messages)do if m.role=="system"then system[#system+1]=m.content else msgs[#msgs+1]={role=m.role,content=m.content}end end url="https://api.anthropic.com/v1/messages"headers={["x-api-key"]=s.apiKey,["anthropic-version"]="2023-06-01",["Content-Type"]="application/json",}body=JSON.encode({model=model,max_tokens=4096,system=table.concat(system,"\n"),messages=msgs,})elseif provider=="Google"then local system={}local contents={}for _,m in ipairs(messages)do if m.role=="system"then system[#system+1]=m.content else local role=(m.role=="assistant")and"model"or"user"contents[#contents+1]={role=role,parts={{text=m.content}}}end end url="https://generativelanguage.googleapis.com/v1beta/models/"..model..":generateContent?key="..s.apiKey headers={["Content-Type"]="application/json"}body=JSON.encode({system_instruction={parts={{text=table.concat(system,"\n")}}},contents=contents,})else url="https://api.openai.com/v1/chat/completions"headers={["Authorization"]="Bearer "..s.apiKey,["Content-Type"]="application/json",}body=JSON.encode({model=model,temperature=0.3,messages=messages,})end local ok,res=pcall(req,{Url=url,Method="POST",Headers=headers,Body=body})if not ok or type(res)~="table"then return false,"request failed: "..tostring(res)end local status=res.StatusCode or res.Status or 0 if type(res.Body)~="string"or res.Body==""then return false,"empty response (status "..tostring(status)..")"end local decodeOk,decoded=pcall(JSON.decode,res.Body)if not decodeOk or type(decoded)~="table"then return false,"bad JSON (status "..tostring(status)..")"end if decoded.error then local msg=type(decoded.error)=="table"and decoded.error.message or tostring(decoded.error)return false,"api error: "..tostring(msg)end local content if provider=="Anthropic"then if decoded.content then local parts={}for _,p in ipairs(decoded.content)do if p.type=="text"and p.text then parts[#parts+1]=p.text end end content=table.concat(parts)end elseif provider=="Google"then local cand=decoded.candidates and decoded.candidates[1]if cand and cand.content and cand.content.parts then local parts={}for _,p in ipairs(cand.content.parts)do if p.text then parts[#parts+1]=p.text end end content=table.concat(parts)end else content=decoded.choices and decoded.choices[1]and decoded.choices[1].message and decoded.choices[1].message.content end if type(content)~="string"or content:gsub("%s","")==""then return false,"no content in response (status "..tostring(status)..")"end return true,content end local function stripFence(text)local inner=text:match("^%s*```[%w]*%s*\n(.-)\n?%s*```%s*$")return inner or text end local function parseToolCall(text)local t=stripFence(text)t=t:gsub("^%s+",""):gsub("%s+$","")if t:sub(1,1)~="{"then return nil end local ok,decoded=pcall(JSON.decode,t)if ok and type(decoded)=="table"and type(decoded.tool)=="string"then return{tool=decoded.tool,args=type(decoded.args)=="table"and decoded.args or{}}end return nil end local function extractCode(text)local c=text:match("```lua%s*\n(.-)```")or text:match("```%s*\n(.-)```")if c and c:gsub("%s","")~=""then return c end return nil end AIChat.extractCode=extractCode local function streamOut(text,onEvent,token)AIChat.lastCode=extractCode(text)or AIChat.lastCode onEvent("assistant_begin")local n=#text local chunkSize=math.max(2,math.floor(n/160))local i=1 while i<=n do if token.cancelled then onEvent("assistant_delta",text:sub(i))break end onEvent("assistant_delta",text:sub(i,i+chunkSize-1))i=i+chunkSize task.wait(0.012)end onEvent("assistant_end")end function AIChat.send(userText,onEvent)ensureInit()if AIChat.busy then onEvent("error","still working on the previous message...")return end if type(userText)~="string"or userText:gsub("%s","")==""then return end local token={cancelled=false}AIChat.current=token AIChat.busy=true table.insert(AIChat.messages,{role="user",content=userText})onEvent("user",userText)task.spawn(function()local steps=0 local finished=false while steps<MAX_STEPS do if token.cancelled then onEvent("status","stopped.")finished=true break end steps=steps+1 onEvent("status",steps>1 and("thinking... (step "..steps..")")or"thinking...")local ok,text=chatComplete(AIChat.messages)if token.cancelled then onEvent("status","stopped.")finished=true break end if not ok then onEvent("error",text)finished=true break end table.insert(AIChat.messages,{role="assistant",content=text})local call=parseToolCall(text)if call then local argsStr=""pcall(function()argsStr=JSON.encode(call.args)end)onEvent("tool",call.tool.." "..argsStr)local result=GameTools.run(call.tool,call.args)onEvent("toolresult",result)table.insert(AIChat.messages,{role="user",content="TOOL RESULT ("..call.tool.."):\n"..result,})else streamOut(text,onEvent,token)finished=true break end end if not finished then onEvent("error","reached the tool-step limit; ask again or be more specific")end AIChat.busy=false AIChat.current=nil onEvent("done")end)end return AIChat end)__bundle_register("Features/Custom/GameTools",function(require,_LOADED,__bundle_register,__bundle_modules)local Custom=require("Features/Custom/Custom")local GameTools={}local Players=game:GetService("Players")local function resolvePath(path)if type(path)~="string"or path:gsub("%s","")==""then return game end path=path:gsub("/",".")local cur=game local first=true for token in path:gmatch("[^%.]+")do if first and(token=="game"or token=="Game"or token=="DataModel")then cur=game elseif token=="LocalPlayer"then cur=Players.LocalPlayer if not cur then return nil,"LocalPlayer is nil"end elseif token=="Character"and typeof(cur)=="Instance"and cur:IsA("Player")then cur=cur.Character if not cur then return nil,"Character is nil"end else local nextInst=nil if cur==game then pcall(function()nextInst=game:GetService(token)end)end if not nextInst then nextInst=cur:FindFirstChild(token)end if not nextInst then return nil,"not found: '"..token.."' under "..cur:GetFullName()end cur=nextInst end first=false end return cur end GameTools.resolvePath=resolvePath local function tExplore(path,depth)local inst,err=resolvePath(path)if not inst then return"Error: "..tostring(err)end depth=math.clamp(tonumber(depth)or 1,1,3)local lines={inst:GetFullName().."  ["..inst.ClassName.."]"}local count=0 local function walk(node,d,indent)if count>=200 then return end local ok,children=pcall(function()return node:GetChildren()end)if not ok then return end for _,child in ipairs(children)do count=count+1 if count>=200 then lines[#lines+1]=indent.."... (truncated)"return end lines[#lines+1]=indent..child.Name.."  ["..child.ClassName.."]"if d>1 then walk(child,d-1,indent.."  ")end end end walk(inst,depth,"  ")if count==0 then lines[#lines+1]="  (no children)"end return table.concat(lines,"\n")end local PROP_CANDIDATES={"Name","ClassName","Enabled","Value","Visible","Transparency","Anchored","CanCollide","Position","Size","Orientation","CFrame","Health","MaxHealth","WalkSpeed","JumpPower","HipHeight","DisplayName","Text","PlaceholderText","Color","BrickColor","Material","Massless","CollisionGroup","MeshId","TextureId","SoundId","Volume","Playing","TimePosition","AssetId","AnimationId","PrimaryPart","Adornee","Active",}local function tProperties(path)local inst,err=resolvePath(path)if not inst then return"Error: "..tostring(err)end local out={inst:GetFullName().."  ["..inst.ClassName.."]"}for _,p in ipairs(PROP_CANDIDATES)do local ok,v=pcall(function()return inst[p]end)if ok and v~=nil then out[#out+1]=p.." = "..tostring(v)end end pcall(function()if inst.Parent then out[#out+1]="Parent = "..inst.Parent:GetFullName()end end)local okA,attrs=pcall(function()return inst:GetAttributes()end)if okA and type(attrs)=="table"then for k,v in pairs(attrs)do out[#out+1]="@"..tostring(k).." = "..tostring(v)end end return table.concat(out,"\n")end local function matchClass(className,filter)if filter==nil or filter==""then return true end return className==filter end local function tSearch(query,class,rootPath)local root,err=resolvePath(rootPath or"game")if not root then return"Error: "..tostring(err)end query=tostring(query or""):lower()local results={}local scanned=0 local ok,descendants=pcall(function()return root:GetDescendants()end)if not ok then return"Error: could not enumerate descendants."end for _,d in ipairs(descendants)do scanned=scanned+1 if scanned>60000 then break end if matchClass(d.ClassName,class)and(query==""or d.Name:lower():find(query,1,true))then results[#results+1]=d:GetFullName().."  ["..d.ClassName.."]"if#results>=60 then results[#results+1]="... (more results omitted)"break end end end if#results==0 then return"No matches (scanned "..scanned.." descendants)."end return table.concat(results,"\n")end local SCRIPT_CLASSES={LocalScript=true,ModuleScript=true,Script=true}local function tScripts(rootPath)local root,err=resolvePath(rootPath or"game")if not root then return"Error: "..tostring(err)end local results={}local scanned=0 local ok,descendants=pcall(function()return root:GetDescendants()end)if not ok then return"Error: could not enumerate descendants."end for _,d in ipairs(descendants)do scanned=scanned+1 if scanned>60000 then break end if SCRIPT_CLASSES[d.ClassName]then results[#results+1]=d:GetFullName().."  ["..d.ClassName.."]"if#results>=80 then results[#results+1]="... (more omitted)"break end end end if#results==0 then return"No scripts found."end return table.concat(results,"\n")end local function tDecompile(path)local inst,err=resolvePath(path)if not inst then return"Error: "..tostring(err)end if not(typeof(inst)=="Instance"and inst:IsA("LuaSourceContainer"))then return"Not a script: "..inst.ClassName end local dec=decompile or(getgenv and getgenv().decompile)if not dec then return"decompile() is not available on this executor."end local ok,src=pcall(dec,inst)if not ok or type(src)~="string"then return"Decompile failed: "..tostring(src)end if#src>9000 then src=src:sub(1,9000).."\n-- [truncated; ask to decompile a nested module for more]"end return src end function GameTools.run(name,args)args=args or{}local ok,result=pcall(function()if name=="explore"then return tExplore(args.path,args.depth)elseif name=="properties"then return tProperties(args.path)elseif name=="search"then return tSearch(args.query,args.class,args.root)elseif name=="scripts"then return tScripts(args.root)elseif name=="decompile"then return tDecompile(args.path)elseif name=="api_reference"then return GameTools.API_REFERENCE elseif name=="run_feature"then local fname=(type(args.name)=="string"and args.name:gsub("%s","")~="")and args.name or"AI Test"if type(args.code)~="string"or args.code:gsub("%s","")==""then return"Error: no 'code' provided."end Custom.save(fname,args.code)local okRun,err=Custom.run(fname,args.code)if okRun then return"Ran '"..fname.."' successfully; its controls are now in the Custom Controls panel. ".."Toggle them to verify behaviour, then give the user the final code in a ```lua block."end return"Run FAILED: "..tostring(err).."\nFix the code and call run_feature again."elseif name=="stop_feature"then local fname=type(args.name)=="string"and args.name or""Custom.stop(fname)return"Stopped '"..fname.."'."elseif name=="list_features"then local names=Custom.list()if#names==0 then return"No saved features."end return table.concat(names,"\n")end return"Unknown tool: "..tostring(name)end)if not ok then return"Tool error: "..tostring(result)end return tostring(result)end GameTools.TOOLS_DOC=table.concat({"TOOLS -- to call one, reply with ONLY a JSON object (no prose, no code fences):",'  {"tool":"explore","args":{"path":"game.Workspace","depth":1}}   -- list children (depth 1-3)','  {"tool":"properties","args":{"path":"game.Players.LocalPlayer.Character.Humanoid"}}','  {"tool":"search","args":{"query":"ClientManager","class":"ModuleScript","root":"game"}}','  {"tool":"scripts","args":{"root":"game.Players.LocalPlayer.PlayerScripts"}}','  {"tool":"decompile","args":{"path":"game.ReplicatedStorage.SomeModule"}}','  {"tool":"api_reference","args":{}}   -- re-read the Aero feature API','  {"tool":"run_feature","args":{"name":"My Feature","code":"<full luau code>"}}  -- TEST your code live; returns success or the error','  {"tool":"stop_feature","args":{"name":"My Feature"}}','  {"tool":"list_features","args":{}}',"Paths are dot paths from the DataModel. Shortcuts: 'LocalPlayer' and '.Character' resolve correctly.","After I return a tool result, keep going: call more tools or give your final answer. One tool per message.","Prefer to TEST feature code with run_feature before finishing -- if it returns an error, fix it and retry.","When you have enough info, reply normally. If you wrote a feature, put the final code in a ```lua block.",},"\n")GameTools.API_REFERENCE=table.concat({"Aero CUSTOM FEATURE API. User code runs in a sandbox inside the 'Aero' Deepwoken exploit menu.","These are available as GLOBAL functions (and under the `Aero` table). Use ONLY this API for UI + lifecycle.","","UI (each returns a control; controls have :get()/:set(v) where sensible, accessed as control.get()/control.set(v)):","  Toggle(text, cb_or_opts)   -- cb_or_opts = function(value) OR { default=bool, callback=fn }","  Button(text, function() end)","  Slider(text, { min=number, max=number, default=number, decimals=number, callback=function(value) end })","  Dropdown(text, { values={...}, default=any, callback=function(value) end })  -- control.setValues(t)","  Input(text, { default=string, callback=function(text) end })  -- or Input(text, function(text) end)","  Keybind(text, { default='E', callback=function(key) end })  -- callback fires when the key is pressed","  Label(text)  -- control.set(text)","  Section(title) -> sub-surface with all the same UI methods","  Window(title) -> a floating draggable window; sub-surface with the same UI methods","","Lifecycle (ALL auto-disconnected when the feature is reloaded/stopped):","  OnRender(function(dt) end)   -- RenderStepped (every frame)","  OnStep(function(dt) end)     -- Heartbeat","  OnInput(function(input, gameProcessed) end)  -- UserInputService.InputBegan","  Interval(seconds, function() end)","  OnCleanup(function() end)","  Notify(text, seconds)","","Game helpers:","  LocalPlayer, Character(), HRP(), Humanoid(), Mouse(), Camera()","  GetTarget() -> nearest target { character, humanoid, root, du=distance } or nil ; GetTargets() -> list","  Value(flag) -> read an existing Aero toggle/option by its flag string","  Toggles, Options -> raw Aero control tables ; Services -> { Players, RunService, Workspace, ... } ; Library","  Standard Roblox globals work: game, workspace, task, math, string, table, Vector3, CFrame, Instance, etc.","","Rules: guard every frame loop with a toggle so it only runs when enabled. Never call loadstring/HttpGet/","setfenv/require inside a feature. Keep code correct and concise. Example:","  local on = Toggle('Enabled', function(v) end)","  Slider('Speed', { min=16, max=200, default=16, callback=function(v)","    local h = Humanoid(); if h then h.WalkSpeed = v end","  end })","  OnRender(function() if not on.get() then return end end)",},"\n")return GameTools end)__bundle_register("Menu/Objects/FloatingWindow",function(require,_LOADED,__bundle_register,__bundle_modules)local Library=require("GUI/Library")local FloatingWindow={}local BAR_H=26 function FloatingWindow.new(opts)opts=opts or{}local size=opts.size or UDim2.fromOffset(360,300)local position=opts.position or UDim2.fromScale(0.5,0.5)local outer=Library:Create("Frame",{Name="LumaFloatingWindow",AnchorPoint=Vector2.new(0.5,0.5),Position=position,Size=size,BackgroundColor3=Library.MainColor,BorderSizePixel=0,Visible=false,ZIndex=200,Parent=Library.ScreenGui,})Library:Create("UICorner",{CornerRadius=UDim.new(0,6),Parent=outer})local st=Library:Create("UIStroke",{Color=Library.AccentColor,Thickness=1,Transparency=0.2,Parent=outer})Library:AddToRegistry(outer,{BackgroundColor3="MainColor"})Library:AddToRegistry(st,{Color="AccentColor"})pcall(function()Library:AddUIScale(outer)end)local bar=Library:Create("Frame",{BackgroundColor3=Library.BackgroundColor,BorderSizePixel=0,Size=UDim2.new(1,0,0,BAR_H),ZIndex=201,Parent=outer,})Library:Create("UICorner",{CornerRadius=UDim.new(0,6),Parent=bar})Library:AddToRegistry(bar,{BackgroundColor3="BackgroundColor"})Library:Create("Frame",{BackgroundColor3=Library.BackgroundColor,BorderSizePixel=0,Position=UDim2.new(0,0,1,-6),Size=UDim2.new(1,0,0,6),ZIndex=201,Parent=bar,})local titleLabel=Library:Create("TextLabel",{BackgroundTransparency=1,Position=UDim2.fromOffset(10,0),Size=UDim2.new(1,-40,1,0),Font=Enum.Font.GothamBold,Text=tostring(opts.title or"Window"),TextSize=13,TextColor3=Library.FontColor,TextXAlignment=Enum.TextXAlignment.Left,TextTruncate=Enum.TextTruncate.AtEnd,ZIndex=202,Parent=bar,})Library:AddToRegistry(titleLabel,{TextColor3="FontColor"})local closeBtn=Library:Create("TextButton",{AnchorPoint=Vector2.new(1,0.5),Position=UDim2.new(1,-6,0.5,0),Size=UDim2.fromOffset(18,18),BackgroundTransparency=1,AutoButtonColor=false,Font=Enum.Font.GothamBold,Text="X",TextSize=