al nl=code:find("\n",i,true)local chunk=nl and code:sub(i,nl-1)or code:sub(i)out[#out+1]=span(HL_COMMENT,chunk)i=i+#chunk end elseif c=='"'or c=="'"then local j=i+1 while j<=n do local cj=code:sub(j,j)if cj=="\\"then j=j+2 elseif cj==c or cj=="\n"then j=j+1 break else j=j+1 end end local chunk=code:sub(i,j-1)out[#out+1]=span(HL_STRING,chunk)i=i+#chunk elseif c=="["and code:sub(i):match("^%[=*%[")then local eqs=code:sub(i):match("^%[(=*)%[")local close="]"..eqs.."]"local endpos=code:find(close,i+#eqs+2,true)local chunk=endpos and code:sub(i,endpos+#close-1)or code:sub(i)out[#out+1]=span(HL_STRING,chunk)i=i+#chunk elseif c:match("%d")or(c=="."and code:sub(i+1,i+1):match("%d"))then local num=code:sub(i):match("^0[xX]%x+")or code:sub(i):match("^%d*%.?%d+[eE][%+%-]?%d+")or code:sub(i):match("^%d*%.?%d+")or c out[#out+1]=span(HL_NUMBER,num)i=i+#num elseif c:match("[%a_]")then local word=code:sub(i):match("^[%w_]+")if LUA_KEYWORDS[word]then out[#out+1]=span(HL_KEYWORD,word)else out[#out+1]=escapeRich(word)end i=i+#word else out[#out+1]=escapeRich(c)i=i+1 end end return table.concat(out)end CodeEditor.highlight=highlightLua CodeEditor.escape=escapeRich function CodeEditor.create(host,height,placeholder,zbase)local GUTTER_W=34 local PAD=6 local PLACEHOLDER=placeholder or"-- write your feature here"local Z=zbase or 5 local isContainer=typeof(host)~="Instance"local parentInst=isContainer and host.Container or host local holder=Library:Create("Frame",{BackgroundColor3=Library.MainColor,BorderSizePixel=0,Size=UDim2.new(1,-4,0,height),LayoutOrder=9999,ZIndex=Z,Parent=parentInst,})Library:Create("UICorner",{CornerRadius=UDim.new(0,4),Parent=holder})Library:AddToRegistry(holder,{BackgroundColor3="MainColor"})local stroke=Library:Create("UIStroke",{Color=Library.OutlineColor,Thickness=1,Transparency=0.5,Parent=holder,})Library:AddToRegistry(stroke,{Color="OutlineColor"})local gutterHolder=Library:Create("Frame",{BackgroundColor3=Library.BackgroundColor,BackgroundTransparency=0.4,BorderSizePixel=0,ClipsDescendants=true,Position=UDim2.new(0,0,0,PAD),Size=UDim2.new(0,GUTTER_W,1,-PAD*2),ZIndex=Z+1,Parent=holder,})local gutter=Library:Create("TextLabel",{BackgroundTransparency=1,Position=UDim2.new(0,0,0,0),Size=UDim2.new(1,-4,0,0),AutomaticSize=Enum.AutomaticSize.Y,Font=Enum.Font.Code,TextSize=13,TextColor3=Library.OutlineColor,TextXAlignment=Enum.TextXAlignment.Right,TextYAlignment=Enum.TextYAlignment.Top,Text="1",ZIndex=Z+1,Parent=gutterHolder,})local scroll=Library:Create("ScrollingFrame",{BackgroundTransparency=1,BorderSizePixel=0,Position=UDim2.new(0,GUTTER_W+2,0,PAD),Size=UDim2.new(1,-(GUTTER_W+2+PAD),1,-PAD*2),CanvasSize=UDim2.new(0,0,0,0),AutomaticCanvasSize=Enum.AutomaticSize.XY,ScrollingDirection=Enum.ScrollingDirection.XY,ScrollBarThickness=4,ZIndex=Z+1,Parent=holder,})local selectionFrames={}local highlight=Library:Create("TextLabel",{BackgroundTransparency=1,Position=UDim2.new(0,2,0,0),Size=UDim2.new(0,0,0,0),AutomaticSize=Enum.AutomaticSize.XY,RichText=true,Font=Enum.Font.Code,TextSize=13,TextColor3=Color3.fromRGB(150,150,162),TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Top,Text=escapeRich(PLACEHOLDER),ZIndex=Z+1,Parent=scroll,})local box=Library:Create("TextBox",{BackgroundTransparency=1,Position=UDim2.new(0,2,0,0),Size=UDim2.new(0,0,0,0),AutomaticSize=Enum.AutomaticSize.XY,MultiLine=true,ClearTextOnFocus=false,TextEditable=true,TextWrapped=false,Font=Enum.Font.Code,TextSize=13,TextColor3=Library.FontColor,TextTransparency=1,TextXAlignment=Enum.TextXAlignment.Left,TextYAlignment=Enum.TextYAlignment.Top,Text="",PlaceholderText="",ZIndex=Z+2,Parent=scroll,})local TextService=game:GetService("TextService")local HUGE=Vector2.new(1e6,1e6)local LINE_H=15 pcall(function()LINE_H=TextService:GetTextSize("Ag",13,Enum.Font.Code,HUGE).Y end)local caret=Library:Create("Frame",{BackgroundColor3=Library.FontColor,BorderSizePixel=0,Size=UDim2.new(0,1,0,LINE_H),Position=UDim2.new(0,2,0,0),Visible=false,ZIndex=Z+3,Parent=scroll,})Library:AddToRegistry(caret,{BackgroundColor3="FontColor"})local function updateCaret()if not box:IsFocused()then caret.Visible=false return end local pos=box.CursorPosition if pos<1 then caret.Visible=false return end local before=box.Text:sub(1,pos-1)local line=0 for _ in before:gmatch("\n")do line=line+1 end local seg=before:match("[^\n]*$")or""local width=0 pcall(function()width=TextService:GetTextSize(seg,13,Enum.Font.Code,HUGE).X end)caret.Position=UDim2.new(0,2+width,0,line*LINE_H)caret.Visible=true caret.BackgroundTransparency=0 end task.spawn(function()while caret.Parent do task.wait(0.5)if box:IsFocused()and caret.Visible then caret.BackgroundTransparency=caret.BackgroundTransparency==0 and 1 or 0 end end end)local function renderSelection()for _,f in ipairs(selectionFrames)do f:Destroy()end selectionFrames={}local sStart,cPos=box.SelectionStart,box.CursorPosition if sStart==-1 or cPos==-1 or sStart==cPos then return end local a=math.min(sStart,cPos)local b=math.max(sStart,cPos)local text=box.Text local pos=1 for line in(text.."\n"):gmatch("(.-)\n")do local len=#line local lineEndPos=pos+len local selA=math.max(a,pos)local selB=math.min(b,lineEndPos+1)if selB>selA then local col1=math.min(selA-pos,len)local col2=math.min(selB-pos,len)local x1,x2=0,0 pcall(function()x1=TextService:GetTextSize(line:sub(1,col1),13,Enum.Font.Code,HUGE).X x2=TextService:GetTextSize(line:sub(1,col2),13,Enum.Font.Code,HUGE).X end)local lineIdx=0 for _ in text:sub(1,pos-1):gmatch("\n")do lineIdx=lineIdx+1 end local w=x2-x1 if b>lineEndPos then w=w+4 end local sel=Library:Create("Frame",{BackgroundColor3=Library.AccentColor,BackgroundTransparency=0.55,BorderSizePixel=0,Position=UDim2.new(0,2+x1,0,lineIdx*LINE_H),Size=UDim2.new(0,math.max(w,2),0,LINE_H),ZIndex=Z,Parent=scroll,})Library:AddToRegistry(sel,{BackgroundColor3="AccentColor"})selectionFrames[#selectionFrames+1]=sel end pos=lineEndPos+1 end end box:GetPropertyChangedSignal("CursorPosition"):Connect(function()updateCaret()renderSelection()end)box:GetPropertyChangedSignal("SelectionStart"):Connect(renderSelection)box.Focused:Connect(updateCaret)box.FocusLost:Connect(function()caret.Visible=false renderSelection()end)local function refresh()local text=box.Text if text==""then highlight.TextColor3=Color3.fromRGB(150,150,162)highlight.Text=escapeRich(PLACEHOLDER)else highlight.TextColor3=Library.FontColor local ok,colored=pcall(highlightLua,text)highlight.Text=ok and colored or escapeRich(text)end local lines=1 for _ in text:gmatch("\n")do lines=lines+1 end local nums={}for k=1,lines do nums[k]=tostring(k)end gutter.Text=table.concat(nums,"\n")end box:GetPropertyChangedSignal("Text"):Connect(function()refresh()updateCaret()renderSelection()end)scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(function()gutter.Position=UDim2.new(0,0,0,-scroll.CanvasPosition.Y)end)refresh()if isContainer and host.Resize then pcall(function()host:Resize()end)end return{get=function()return box.Text end,set=function(text)box.Text=text or""refresh()end,setEditable=function(editable)box.TextEditable=editable and true or false if not editable then caret.Visible=false end end,}end return CodeEditor end)__bundle_register("GUI/SaveManager",function(require,_LOADED,__bundle_register,__bundle_modules)return LPH_NO_VIRTUALIZE(function()local httpService=game:GetService("HttpService")local function uDIm2Export(udim2)return{xScale=udim2.X.Scale,xOffset=udim2.X.Offset,yScale=udim2.Y.Scale,yOffset=udim2.Y.Offset,}end local function uDim2Import(serialized)return UDim2.new(serialized.xScale,serialized.xOffset,serialized.yScale,serialized.yOffset)end local SaveManager={}do SaveManager.Folder="Aero-Rewrite-Configs"SaveManager.Ignore={}SaveManager.Parser={Toggle={Save=function(idx,object)return{type="Toggle",idx=idx,value=object.Value}end,Load=function(idx,data)if Toggles[idx]then Toggles[idx]:SetValue(data.value)end end,},Slider={Save=function(idx,object)return{type="Slider",idx=idx,value=tostring(object.Value)}end,Load=function(idx,data)if Options[idx]then Options[idx]:SetValue(data.value)end end,},Dropdown={Save=function(idx,object)return{type="Dropdown",idx=idx,value=object.Value,values=object.SaveValues and object.Values or nil,mutli=object.Multi,}end,Load=function(idx,data)if Options[idx]then if data.values then Options[idx]:SetValues(data.values)end Options[idx]:SetValue(data.value)Options[idx]:Display()end end,},ColorPicker={Save=function(idx,object)return{type="ColorPicker",idx=idx,hue=object.Hue,sat=object.Sat,vib=object.Vib,transparency=object.Transparency,rainbow=object.Rainbow,}end,Load=function(idx,data)if Options[idx]then Options[idx].Rainbow=data.rainbow Options[idx]:SetValue({data.hue,data.sat,data.vib},data.transparency)Options[idx]:Display()end end,},KeyPicker={Save=function(idx,object)return{type="KeyPicker",idx=idx,mode=object.Mode,key=object.Value}end,Load=function(idx,data)if Options[idx]then Options[idx]:SetValue({data.key,data.mode})end end,},Input={Save=function(idx,object)return{type="Input",idx=idx,text=object.Value}end,Load=function(idx,data)if Options[idx]and type(data.text)=="string"then Options[idx]:SetValue(data.text)end end,},}function SaveManager:SetIgnoreIndexes(list)for _,key in next,list do self.Ignore[key]=true end end function SaveManager:SetFolder(folder)self.Folder=folder self:BuildFolderTree()end function SaveManager:Save(name)if not name then return false,"no config file is selected"end local fullPath=self.Folder.."/"..name..".json"local data={objects={},keybindFramePosition=uDIm2Export(self.Library.KeybindFrame.Position),watermarkFramePosition=uDIm2Export(self.Library.Watermark.Position),infoLoggerFramePosition=uDIm2Export(self.Library.InfoLoggerFrame.Position),infoLoggerBlacklistHistory=self.Library.InfoLoggerData.KeyBlacklistHistory,infoLoggerBlacklist=self.Library.InfoLoggerData.KeyBlacklistList,infoLoggerCycle=self.Library.InfoLoggerData.InfoLoggerCycle,animationVisualizerFramePosition=uDIm2Export(self.Library.AnimationVisualizerFrame.Position),overrideData=self.Library.OverrideData,}for idx,toggle in next,Toggles do if self.Ignore[idx]then continue end table.insert(data.objects,self.Parser[toggle.Type].Save(idx,toggle))end for idx,option in next,Options do if not self.Parser[option.Type]then continue end if self.Ignore[idx]then continue end table.insert(data.objects,self.Parser[option.Type].Save(idx,option))end local success,encoded=pcall(httpService.JSONEncode,httpService,data)if not success then return false,"failed to encode data"end writefile(fullPath,encoded)return true end function SaveManager:Load(name)if not name then return false,"no config file is selected"end local file=self.Folder.."/"..name..".json"if not isfile(file)then return false,"invalid file"end local success,decoded=pcall(httpService.JSONDecode,httpService,readfile(file))if not success then return false,"decode error"end if decoded.keybindFramePosition then self.Library.KeybindFrame.Position=uDim2Import(decoded.keybindFramePosition)end if decoded.watermarkFramePosition then self.Library.Watermark.Position=uDim2Import(decoded.watermarkFramePosition)end if decoded.infoLoggerFramePosition then self.Library.InfoLoggerFrame.Position=uDim2Import(decoded.infoLoggerFramePosition)end if decoded.infoLoggerBlacklistHistory then self.Library.InfoLoggerData.KeyBlacklistHistory=decoded.infoLoggerBlacklistHistory end if decoded.animationVisualizerFramePosition then self.Library.AnimationVisualizerFrame.Position=uDim2Import(decoded.animationVisualizerFramePosition)end local timingList=Options["TimingOverrideList"]if decoded.overrideData and timingList then self.Library.OverrideData=decoded.overrideData local values={}for rname,_ in next,decoded.overrideData do values[#values+1]=rname end timingList:SetValues(values)end local applied=0 for _,option in next,decoded.objects do if not self.Ignore[option.idx]and self.Parser[option.type]then task.spawn(function()self.Parser[option.type].Load(option.idx,option)end)applied=applied+1 if applied%25==0 then task.wait()end end end if decoded.infoLoggerBlacklist then self.Library.InfoLoggerData.KeyBlacklistList=decoded.infoLoggerBlacklist self.Library:RefreshInfoLogger()if Options and Options.BlacklistedKeys then Options.BlacklistedKeys:SetValues(self.Library:KeyBlacklists())end end if decoded.infoLoggerCycle then self.Library.InfoLoggerData.InfoLoggerCycle=decoded.infoLoggerCycle self.Library:RefreshInfoLogger()if Options and Options.BlacklistedKeys then Options.BlacklistedKeys:SetValues(self.Library:KeyBlacklists())end end return true end function SaveManager:IgnoreThemeSettings()self:SetIgnoreIndexes({"BackgroundColor","MainColor","AccentColor","OutlineColor","FontColor","ThemeManager_ThemeList","ThemeManager_CustomThemeList","ThemeManager_CustomThemeName",})end function SaveManager:BuildFolderTree()local paths={self.Folder,}for i=1,#paths do local str=paths[i]if not isfolder(str)then makefolder(str)end end end function SaveManager:RefreshConfigList()local list=listfiles(self.Folder)local out={}for i=1,#list do local file=list[i]if file:sub(-5)==".json"then local pos=file:find(".json",1,true)local start=pos local char=file:sub(pos,pos)while char~="/"and char~="\\"and char~=""do pos=pos-1 char=file:sub(pos,pos)end if char=="/"or char=="\\"then table.insert(out,file:sub(pos+1,start-1))end end end return out end function SaveManager:SetLibrary(library)self.Library=library end function SaveManager:LoadAutoloadConfig()if isfile(self.Folder.."/autoload.txt")then local name=readfile(self.Folder.."/autoload.txt")local success,err=self:Load(name)if not success then return self.Library:Notify("Failed to load autoload config: "..err)end end end function SaveManager:BuildConfigSection(tab)assert(self.Library,"Must set SaveManager.Library")local section=tab:AddFullGroupbox("Config Manager")section:AddInput("SaveManager_ConfigName",{Text="Config name"})section:AddDropdown("SaveManager_ConfigList",{Text="Config list",Values=self:RefreshConfigList(),AllowNull=true})section:AddDivider()section:AddButton("Create config",function()local name=Options.SaveManager_ConfigName.Value if name:gsub(" ","")==""then return self.Library:Notify("Invalid config name (empty)",2)end local success,err=self:Save(name)if not success then return self.Library:Notify("Failed to save config: "..err)end self.Library:Notify(string.format("Created config %q",name))Options.SaveManager_ConfigList:SetValues(self:RefreshConfigList())Options.SaveManager_ConfigList:SetValue(nil)end):AddButton("Load config",function()local name=Options.SaveManager_ConfigList.Value local success,err=self:Load(name)if not success then return self.Library:Notify("Failed to load config: "..err)end self.Library:Notify(string.format("Loaded config %q",name))end)section:AddButton("Overwrite config",function()local name=Options.SaveManager_ConfigList.Value local success,err=self:Save(name)if not success then return self.Library:Notify("Failed to overwrite config: "..err)end self.Library:Notify(string.format("Overwrote config %q",name))end)section:AddButton("Refresh list",function()Options.SaveManager_ConfigList:SetValues(self:RefreshConfigList())Options.SaveManager_ConfigList:SetValue(nil)end)section:AddButton("Set as autoload",function()local name=Options.SaveManager_ConfigList.Value if type(name)~="string"or name:gsub(" ","")==""then return self.Library:Notify("No config selected to set as autoload",2)end writefile(self.Folder.."/autoload.txt",name)SaveManager.AutoloadLabel:SetText("Current autoload config: "..name)self.Library:Notify(string.format("Set %q to auto load",name))end)section:AddButton("Clear autoload",function()local path=self.Folder.."/autoload.txt"if not isfile(path)then return self.Library:Notify("No autoload config is set",2)end delfile(path)SaveManager.AutoloadLabel:SetText("Current autoload config: none")self.Library:Notify("Cleared autoload config")end)SaveManager.AutoloadLabel=section:AddLabel("Current autoload config: none",true)if isfile(self.Folder.."/autoload.txt")then local name=readfile(self.Folder.."/autoload.txt")SaveManager.AutoloadLabel:SetText("Current autoload config: "..name)end SaveManager:SetIgnoreIndexes({"SaveManager_ConfigList","SaveManager_ConfigName"})end SaveManager:BuildFolderTree()end return SaveManager end)()end)__bundle_register("GUI/Icons",function(require,_LOADED,__bundle_register,__bundle_modules)return{Combat={Id=16898787671,Offset=Vector2.new(514,514),Size=Vector2.new(256,256)},Visuals={Id=16898669897,Offset=Vector2.new(0,0),Size=Vector2.new(256,256)},Game={Id=16898672166,Offset=Vector2.new(257,0),Size=Vector2.new(256,256)},Auto={Id=16898617146,Offset=Vector2.new(0,0),Size=Vector2.new(256,256)},Exploit={Id=16898734564,Offset=Vector2.new(0,0),Size=Vector2.new(256,256)},Settings={Id=16898734421,Offset=Vector2.new(514,0),Size=Vector2.new(256,256)},Builder={Id=16898791187,Offset=Vector2.new(514,257),Size=Vector2.new(256,256)},}end)__bundle_register("Menu/AdminTab",function(require,_LOADED,__bundle_register,__bundle_modules)local AdminTab={}local Library=require("GUI/Library")local Logger=require("Utility/Logger")local Admin=require("Features/Admin")local Monitoring=require("Features/Game/Monitoring")local AnimationFlooder=require("Features/Exploits/AnimationFlooder")local AnimationInspector=require("Features/Combat/AnimationInspector")local Players=game:GetService("Players")local TP_DESTINATIONS={"EasternLuminant","EtreanLuminant","Depths","Voidheart","TrialOfOne","GuildDoor",}local function playerFromName(name)if type(name)~="string"or name==""then return nil end for _,plr in next,Players:GetPlayers()do if plr.Name==name then return plr end end return nil end local function selectedName()local option=Options and Options["AdminTarget"]return option and option.Value or nil end local function targetToken(name)local localPlayer=Players.LocalPlayer if localPlayer and name==localPlayer.Name then return"me"end return name end local function runCommand(cmd,extra)local name=selectedName()if not name then return Logger.notify("Admin panel: pick a player first.")end if Admin.sendCommand(cmd,targetToken(name),extra)then Logger.notify("Admin panel: sent '%s' to %s.",cmd,name)else Logger.notify("Admin panel: failed to send '%s' (no chat channel).",cmd)end end local function spectateSelected()local name=selectedName()if not name then return Logger.notify("Admin panel: pick a player to spectate.")end local player=playerFromName(name)if not player then return Logger.notify("Admin panel: '%s' is no longer in the server.",name)end if player==Players.LocalPlayer then Monitoring.subject=nil return Logger.notify("Admin panel: that's you -- camera reset.")end local character=player.Character local humanoidRootPart=character and character:FindFirstChild("HumanoidRootPart")if not humanoidRootPart then return Logger.notify("Admin panel: '%s' isn't loaded in yet.",name)end Monitoring.subject=humanoidRootPart Logger.notify("Admin panel: spectating %s.",name)end local function stopSpectating()Monitoring.subject=nil Logger.notify("Admin panel: stopped spectating.")end function AdminTab.init(window)local localPlayer=Players.LocalPlayer if not localPlayer then return end if not Admin.isDeveloper(localPlayer.UserId)then return end local tab=window:AddTab("Admin")local roster=tab:AddLeftGroupbox("Players")roster:AddDropdown("AdminTarget",{Text="Target Player",SpecialType="Player",AllowNull=true,Tooltip="Every player in the server, yourself included. Drives the admin commands.",})roster:AddButton({Text="Spectate Selected",Func=spectateSelected,Tooltip="Lock your camera onto the selected player.",})roster:AddButton({Text="Stop Spectating",Func=stopSpectating,})roster:AddButton({Text="Bring To Me",Func=function()runCommand("bring")end,Tooltip="Pull the selected player to your position.",})local cmds=tab:AddRightGroupbox("Commands")cmds:AddButton({Text="Freeze",Func=function()runCommand("freeze")end,Tooltip="Anchor the target in place.",})cmds:AddButton({Text="Unfreeze",Func=function()runCommand("unfreeze")end,})cmds:AddButton({Text="Kill",DoubleClick=true,Tooltip="Double-click. Sends max fall damage to the target.",Func=function()runCommand("kill")end,})cmds:AddButton({Text="Kick",DoubleClick=true,Tooltip="Double-click. Kicks the target, naming you as the admin.",Func=function()runCommand("kick")end,})cmds:AddButton({Text="Fake Ban",DoubleClick=true,Tooltip="Double-click. Kicks the target with a fake moderation-ban notice.",Func=function()runCommand("fakeban")end,})cmds:AddButton({Text="Unload Their Aero",DoubleClick=true,Tooltip="Double-click. Force-unloads Aero on the target's client.",Func=function()runCommand("unload")end,})cmds:AddButton({Text="Fake Agamatsu",Func=function()runCommand("fakeagamatsu")end,Tooltip="Fires a counterfeit 'Agamatsu is staff' alert on the target.",})local tp=tab:AddRightGroupbox("Teleport")tp:AddDropdown("AdminTpDestination",{Text="Destination",Values=TP_DESTINATIONS,Default=TP_DESTINATIONS[1],Tooltip="Where ;tp sends the selected player.",})tp:AddButton({Text="Teleport Selected",Func=function()local option=Options and Options["AdminTpDestination"]runCommand("tp",option and option.Value or nil)end,})local flood=tab:AddLeftGroupbox("Forge Ban")local function flooderNames()local names={}for _,p in ipairs(Players:GetPlayers())do if p~=Players.LocalPlayer then names[#names+1]=p.Name end end table.sort(names)return names end local flooderInitial=flooderNames()local flooderDropdown=flood:AddDropdown("AnimationFlooderTarget",{Text="Target Player",Values=flooderInitial,Default=flooderInitial[1]or"",Multi=false,AllowNull=true,Tooltip="Which player to flood animations on.",Callback=function(name)AnimationFlooder.setTargetByName(name)end,})flood:AddButton({Text="Refresh Player List",Func=function()pcall(function()flooderDropdown:SetValues(flooderNames())end)end,})flood:AddSlider("AnimationFlooderIntensity",{Text="Intensity",Default=8,Min=1,Max=50,Rounding=0,Tooltip="Flood animations played per second on the target.",})local floodToggle=flood:AddToggle("AnimationFlooder",{Text="Flood Player Animations",Default=false,Tooltip="Plays every decoy attack animation on the selected player's character.",})floodToggle:OnChanged(function(state)if state then AnimationFlooder.startByName(flooderDropdown.Value)else AnimationFlooder.stop()end end)floodToggle:AddKeyPicker("AnimationFlooderKeybind",{Default="N/A",SyncToggleState=true,Text="Flood Player Animations"})Players.PlayerAdded:Connect(function()pcall(function()flooderDropdown:SetValues(flooderNames())end)end)Players.PlayerRemoving:Connect(function()pcall(function()flooderDropdown:SetValues(flooderNames())end)end)local logger=tab:AddLeftGroupbox("Animation Logger")logger:AddDivider()local function inspectNames()local names={}local lp=Players.LocalPlayer for _,p in ipairs(Players:GetPlayers())do if p~=lp then names[#names+1]=p.Name end end table.sort(names)if lp then table.insert(names,1,lp.Name)end return names end local inspectInitial=inspectNames()local inspectDropdown=logger:AddDropdown("AnimInspectTarget",{Text="Inspect Player",Values=inspectInitial,Default=inspectInitial[1]or"",Multi=false,AllowNull=true,Tooltip="Which player's live animations to show in the inspector window. You're listed first, so leave it as-is to watch your own.",Callback=function(name)AnimationInspector.setTargetByName(name)end,})logger:AddButton({Text="Refresh Player List",Func=function()pcall(function()inspectDropdown:SetValues(inspectNames())end)end,})logger:AddToggle("AnimInspectLogToFile",{Text="Log to File",Default=false,Tooltip="While the inspector runs, write the target's animation name/id/priority (and any change to them) to luma_animlog.txt in your executor's workspace folder.",})local inspectToggle=logger:AddToggle("AnimationInspector",{Text="Animation Inspector",Default=false,Tooltip="Opens a live window listing every animation the selected player is currently playing. Rows appear as animations start and are DELETED the moment each one ends.",})inspectToggle:OnChanged(function(state)if state then AnimationInspector.startByName(inspectDropdown.Value)else AnimationInspector.stop()end end)Players.PlayerAdded:Connect(function()pcall(function()inspectDropdown:SetValues(inspectNames())end)end)Players.PlayerRemoving:Connect(function()pcall(function()inspectDropdown:SetValues(inspectNames())end)end)end return AdminTab end)__bundle_register("Menu/ConfigTab",function(require,_LOADED,__bundle_register,__bundle_modules)local ConfigTab={}local Icons=require("GUI/Icons")local SaveManager=require("GUI/SaveManager")function ConfigTab.init(window)local tab=window:AddTab("Config","Settings",Icons.Builder)SaveManager:BuildConfigSection(tab)end return ConfigTab end)__bundle_register("Menu/UtilityTab",function(require,_LOADED,__bundle_register,__bundle_modules)local UtilityTab={}local Icons=require("GUI/Icons")function UtilityTab.init(window)local GameTab=require("Menu/GameTab")local VisualsTab=require("Menu/VisualsTab")local ExploitTab=require("Menu/ExploitTab")local tab=window:AddTab("Utility","Utility",Icons.Exploit)local tabbox=tab:AddFullTabbox()GameTab.initMovementSection(tabbox:AddTab("Movement"))local exploitsTab=tabbox:AddTab("Exploits")ExploitTab.initMobExploitsSection(exploitsTab)ExploitTab.initLocalCharacterExploitsSection(exploitsTab)VisualsTab.initMorphLoaderSection(exploitsTab)local realmOk=true pcall(function()local replicatedStorage=game:GetService("ReplicatedStorage")local info=replicatedStorage:WaitForChild("Info",5)local realmInfo=info and info:WaitForChild("RealmInfo",5)local currentWorld=(realmInfo and require(realmInfo).CurrentWorld)or"N/A"if currentWorld=="Depths"or currentWorld=="Mission"or currentWorld=="Dungeon"then realmOk=false end end)if realmOk then ExploitTab.initTeleportsSection(tabbox)end GameTab.initPlayerMonitoringSection(tabbox:AddTab("Monitoring"))GameTab.initInfoSpoofingSection(tabbox:AddTab("Info"))local trackersTab=tabbox:AddTab("Trackers")VisualsTab.initVisualAssistanceSection(trackersTab)GameTab.initRevea