UTE="LumaMorphOriginalTransparency"local AVATAR_COLOR_ATTRIBUTE="LumaMorphAvatarOriginalColor"local MORPH_FORWARD={}local MORPH_NOHIDE={}local MORPH_KEEP_VISIBLE={}local currentCategory="Races"local currentFile=nil local savedMorph=PersistentData.get("morphResume")local serverHopEnabled=type(savedMorph)=="table"and savedMorph.enabled==true local activeMorph=nil if serverHopEnabled and type(savedMorph.kind)=="string"then if savedMorph.kind=="file"and FOLDERS[savedMorph.category]and type(savedMorph.file)=="string"and savedMorph.file~=""then activeMorph={kind="file",category=savedMorph.category,file=savedMorph.file,}elseif savedMorph.kind=="avatar"and type(savedMorph.username)=="string"then activeMorph={kind="avatar",username=savedMorph.username,}end end local hideBodyEnabled=true local hideHeadFaceEnabled=true local reapplyEnabled=false local hideToggle local RunService=game:GetService("RunService")local hideConn=nil local hiddenList={}local function saveMorphResume()if not serverHopEnabled then PersistentData.set("morphResume",nil)return end local data={enabled=true}if activeMorph then data.kind=activeMorph.kind data.category=activeMorph.category data.file=activeMorph.file data.username=activeMorph.username end PersistentData.set("morphResume",data)end local function listMorphs(dir)if type(listFiles)~="function"then return{}end local ok,res=pcall(listFiles,dir)if not ok or type(res)~="table"then return{}end local out={}for _,p in ipairs(res)do local path=tostring(p):gsub("\\","/")if path:sub(-5):lower()==".rbxm"then local name=path:match("([^/]+)%.rbxm$")if name then table.insert(out,name)end end end table.sort(out)return out end local function getChar()local c=lp.Character if not c then return nil end if not c:FindFirstChild("HumanoidRootPart")then c:WaitForChild("HumanoidRootPart",5)end return c end local function stopHide()if hideConn then hideConn:Disconnect();hideConn=nil end for _,p in ipairs(hiddenList)do if p and p.Parent then pcall(function()if p:IsA("BasePart")then local originalLtm=p:GetAttribute(HIDDEN_LTM_ATTRIBUTE)p.LocalTransparencyModifier=originalLtm or 0 p:SetAttribute(HIDDEN_LTM_ATTRIBUTE,nil)local originalTransparency=p:GetAttribute(HIDDEN_TRANSPARENCY_ATTRIBUTE)if originalTransparency~=nil then p.Transparency=originalTransparency end p:SetAttribute(HIDDEN_TRANSPARENCY_ATTRIBUTE,nil)end if p:GetAttribute("LumaMorphHidden")~=nil then p.Transparency=p:GetAttribute("LumaMorphHidden")p:SetAttribute("LumaMorphHidden",nil)end end)end end hiddenList={}end local function startHide(parts)stopHide()hiddenList=parts hideConn=RunService.RenderStepped:Connect(function()for _,p in ipairs(hiddenList)do if p and p.Parent then if p:IsA("BasePart")then if p:GetAttribute(HIDDEN_LTM_ATTRIBUTE)==nil then p:SetAttribute(HIDDEN_LTM_ATTRIBUTE,p.LocalTransparencyModifier)end if p:GetAttribute(HIDDEN_TRANSPARENCY_ATTRIBUTE)==nil then p:SetAttribute(HIDDEN_TRANSPARENCY_ATTRIBUTE,p.Transparency)end p.LocalTransparencyModifier=1 else p.Transparency=1 end end end end)end local function clearMorphs()stopHide()local c=lp.Character if not c then return end for _,p in ipairs(c:GetDescendants())do if p:IsA("BasePart")then local originalLtm=p:GetAttribute(HIDDEN_LTM_ATTRIBUTE)if originalLtm~=nil then p.LocalTransparencyModifier=originalLtm p:SetAttribute(HIDDEN_LTM_ATTRIBUTE,nil)elseif p.LocalTransparencyModifier>0 then p.LocalTransparencyModifier=0 end local originalTransparency=p:GetAttribute(HIDDEN_TRANSPARENCY_ATTRIBUTE)if originalTransparency~=nil then p.Transparency=originalTransparency p:SetAttribute(HIDDEN_TRANSPARENCY_ATTRIBUTE,nil)end end end for _,p in ipairs(c:GetChildren())do if p:GetAttribute("LumaMorphClothing")or p:GetAttribute("LumaMorphAccessory")or p:GetAttribute("LumaMorphBodyColors")or p:GetAttribute("LumaMorphCharacterMesh")then p:Destroy()end end local backup=c:FindFirstChild(BACKUP_NAME)if backup then for _,p in ipairs(backup:GetChildren())do p.Parent=c end backup:Destroy()end local h=c:FindFirstChild(HOLDER_NAME)if h then h:Destroy()end for _,p in ipairs(c:GetDescendants())do if p:GetAttribute("LumaMorphFaceClone")then p:Destroy()elseif p:GetAttribute("LumaMorphFace")~=nil then pcall(function()p.Texture=p:GetAttribute("LumaMorphFace")end)p:SetAttribute("LumaMorphFace",nil)end end for _,p in ipairs(c:GetDescendants())do if p:GetAttribute("LumaMorphHidden")~=nil then pcall(function()p.Transparency=p:GetAttribute("LumaMorphHidden")end)p:SetAttribute("LumaMorphHidden",nil)end end for _,p in ipairs(c:GetDescendants())do if p:GetAttribute("LumaMorphSkin")~=nil then pcall(function()p.Color=p:GetAttribute("LumaMorphSkin")end)p:SetAttribute("LumaMorphSkin",nil)end if p:GetAttribute(AVATAR_COLOR_ATTRIBUTE)~=nil then pcall(function()p.Color=p:GetAttribute(AVATAR_COLOR_ATTRIBUTE)end)p:SetAttribute(AVATAR_COLOR_ATTRIBUTE,nil)end end end local LIMB_NAMES={"Head","UpperTorso","LowerTorso","LeftUpperArm","LeftLowerArm","LeftHand","RightUpperArm","RightLowerArm","RightHand","LeftUpperLeg","LeftLowerLeg","LeftFoot","RightUpperLeg","RightLowerLeg","RightFoot","Torso","Left Arm","Right Arm","Left Leg","Right Leg",}local ANCHOR_NAMES={"HumanoidRootPart","UpperTorso","Torso","LowerTorso","tt","t","lt","Chestplate","Body","Root","Middle",}local function collectLimbs(char)local limbs={}for _,name in ipairs(LIMB_NAMES)do local p=char:FindFirstChild(name)if p and p:IsA("BasePart")then limbs[#limbs+1]=p end end return limbs end local function findCharAnchor(char)return char:FindFirstChild("UpperTorso")or char:FindFirstChild("Torso")or char:FindFirstChild("LowerTorso")or char:FindFirstChild("HumanoidRootPart")end local function findMorphAnchor(model)for _,an in ipairs(ANCHOR_NAMES)do local p=model:FindFirstChild(an,true)if p and p:IsA("BasePart")then return p end end return model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart",true)end local function nearestLimb(limbs,pos)local best,bestDist for _,l in ipairs(limbs)do local d=(l.Position-pos).Magnitude if not bestDist or d<bestDist then bestDist,best=d,l end end return best end local LIMB_HINTS={{"uppertorso",{"UpperTorso"}},{"lowertorso",{"LowerTorso"}},{"torso",{"UpperTorso","Torso","LowerTorso"}},{"chest",{"UpperTorso","Torso"}},{"head",{"Head"}},{"face",{"Head"}},{"hair",{"Head"}},{"hat",{"Head"}},{"horn",{"Head"}},{"mask",{"Head"}},{"helm",{"Head"}},{"shading",{"Head"}},{"shade",{"Head"}},{"lefthand",{"LeftHand","Left Arm"}},{"righthand",{"RightHand","Right Arm"}},{"leftlowerarm",{"LeftLowerArm","Left Arm"}},{"rightlowerarm",{"RightLowerArm","Right Arm"}},{"leftupperarm",{"LeftUpperArm","Left Arm"}},{"rightupperarm",{"RightUpperArm","Right Arm"}},{"leftarm",{"LeftUpperArm","Left Arm"}},{"rightarm",{"RightUpperArm","Right Arm"}},{"leftfoot",{"LeftFoot","Left Leg"}},{"rightfoot",{"RightFoot","Right Leg"}},{"leftlowerleg",{"LeftLowerLeg","Left Leg"}},{"rightlowerleg",{"RightLowerLeg","Right Leg"}},{"leftupperleg",{"LeftUpperLeg","Left Leg"}},{"rightupperleg",{"RightUpperLeg","Right Leg"}},{"leftleg",{"LeftUpperLeg","Left Leg"}},{"rightleg",{"RightUpperLeg","Right Leg"}},{"arm",{"UpperTorso","Torso"}},}local function limbFromName(char,name)local n=tostring(name):lower():gsub("[^%w]","")for _,pair in ipairs(LIMB_HINTS)do if n:find(pair[1],1,true)then for _,cand in ipairs(pair[2])do local limb=char:FindFirstChild(cand)if limb and limb:IsA("BasePart")then return limb end end end end return nil end local function bindingAttachment(part)local a=part:FindFirstChild("Offset")or part:FindFirstChild("JointOffset")or part:FindFirstChild("Attach")if a and a:IsA("Attachment")then return a end return nil end local MORPH_PART_LIFT={FifthGear={ArmsEquipment_Torso=1.3},}local function partLift(morphName,partName)local base=tostring(morphName):gsub("%s*%(%d+%)%s*$","")local t=MORPH_PART_LIFT[base]return(t and t[partName])or 0 end local MORPH_SKIN={FifthGear=Color3.fromRGB(226,178,132),}local SKIN_LIMBS={"Torso","Left Arm","Right Arm","Left Leg","Right Leg","UpperTorso","LowerTorso","LeftUpperArm","LeftLowerArm","LeftHand","RightUpperArm","RightLowerArm","RightHand","LeftUpperLeg","LeftLowerLeg","LeftFoot","RightUpperLeg","RightLowerLeg","RightFoot",}local R15_LIMB_SET={Head=true,UpperTorso=true,LowerTorso=true,LeftUpperArm=true,LeftLowerArm=true,LeftHand=true,RightUpperArm=true,RightLowerArm=true,RightHand=true,LeftUpperLeg=true,LeftLowerLeg=true,LeftFoot=true,RightUpperLeg=true,RightLowerLeg=true,RightFoot=true,}local function morphBase(name)return tostring(name):gsub("%s*%(%d+%)%s*$","")end local MORPH_RIGID_HEAD={TungTung=true}local MORPH_HIDE_PARTS={Mudskipper={MudskipperHatA=true},}local MORPH_PART_LIMB={}local MORPH_SUBPART_LIFT={ippo={MeshPart=1.5}}local function applyModel(model,hideBody,morphName)local char=getChar()if not char then return false,"no character"end if not char:FindFirstChild("HumanoidRootPart")then return false,"no HumanoidRootPart"end local limbs=collectLimbs(char)if#limbs==0 then return false,"no limbs on character"end local extraHide={}local morphHasHair=false local base=morphBase(morphName)local hideParts=MORPH_HIDE_PARTS[base]if hideParts then for _,p in ipairs(model:GetDescendants())do if p:IsA("BasePart")and hideParts[p.Name]then pcall(function()p:Destroy()end)end end end local partLimbMap=MORPH_PART_LIMB[base]local function overrideLimb(partName)local nm=partLimbMap and partLimbMap[partName]if nm then local l=char:FindFirstChild(nm)if l and l:IsA("BasePart")then return l end end return nil end local rigidHead=MORPH_RIGID_HEAD[base]local partToLimb={}local keepVisible=MORPH_KEEP_VISIBLE[morphName]or{}local originalBits={}for _,p in ipairs(char:GetDescendants())do local isPart=p:IsA("BasePart")and p.Name~="HumanoidRootPart"local isDecal=p:IsA("Decal")or p:IsA("Texture")if isPart or isDecal then local ownerName=isPart and p.Name or(p.Parent and p.Parent.Name)if not(ownerName and keepVisible[ownerName])then if isDecal and p:GetAttribute("LumaMorphHidden")==nil then p:SetAttribute("LumaMorphHidden",p.Transparency)end originalBits[#originalBits+1]=p end end end local cAnchor=findCharAnchor(char)local mAnchor=findMorphAnchor(model)if not cAnchor or not mAnchor then return false,"could not find torso anchor"end local morphWantsHide=model:FindFirstChild("HideBody",true)~=nil local TRUE_TORSO={HumanoidRootPart=true,UpperTorso=true,Torso=true,LowerTorso=true,tt=true,t=true,lt=true,}local trustedAnchor=TRUE_TORSO[mAnchor.Name]==true local T=cAnchor.CFrame*mAnchor.CFrame:Inverse()local driven={}for _,j in ipairs(model:GetDescendants())do if j:IsA("Weld")or j:IsA("Motor6D")or j:IsA("WeldConstraint")or j:IsA("Snap")or j:IsA("ManualWeld")then if j.Part1 then driven[j.Part1]=true end end end for _,p in ipairs(model:GetDescendants())do if p:IsA("BasePart")then p.CFrame=T*p.CFrame end end if not trustedAnchor then local sum,cnt=Vector3.zero,0 for _,p in ipairs(model:GetDescendants())do if p:IsA("BasePart")then sum=sum+p.Position;cnt=cnt+1 end end if cnt>0 then local center=sum/cnt local delta=Vector3.new(cAnchor.Position.X-center.X,0,cAnchor.Position.Z-center.Z)for _,p in ipairs(model:GetDescendants())do if p:IsA("BasePart")then p.CFrame=p.CFrame+delta end end end end local fwdAmount=MORPH_FORWARD[morphName]or 0 if fwdAmount~=0 then local fwd=cAnchor.CFrame.LookVector*fwdAmount for _,p in ipairs(model:GetDescendants())do if p:IsA("BasePart")then p.CFrame=p.CFrame+fwd end end end local rigParts={}for _,p in ipairs(model:GetDescendants())do if p:IsA("BasePart")and R15_LIMB_SET[p.Name]and char:FindFirstChild(p.Name)then rigParts[#rigParts+1]=p end end if#rigParts>=6 then for _,w in ipairs(model:GetDescendants())do if(w:IsA("Weld")or w:IsA("Motor6D")or w:IsA("ManualWeld")or w:IsA("Snap")or w:IsA("WeldConstraint"))and w.Part1 and R15_LIMB_SET[w.Part1.Name]then w:Destroy()end end for _,p in ipairs(rigParts)do local targetName=p.Name local keepPos=false if rigidHead and p.Name=="Head"then if char:FindFirstChild("UpperTorso")then targetName="UpperTorso"elseif char:FindFirstChild("Torso")then targetName="Torso"end keepPos=true end local real=ch