me=="KillPlane"or instance.Name:match("Chasm")~=nil)end local function getBounds(part)local cframe=part.CFrame if cframe.Y~=cframe.Y or math.abs(cframe.Y)==math.huge then return nil end local size=part.Size local right,up,look=cframe.RightVector,cframe.UpVector,cframe.LookVector local extents=Vector3.new(math.abs(right.X)*size.X+math.abs(up.X)*size.Y+math.abs(look.X)*size.Z,math.abs(right.Y)*size.X+math.abs(up.Y)*size.Y+math.abs(look.Y)*size.Z,math.abs(right.Z)*size.X+math.abs(up.Z)*size.Y+math.abs(look.Z)*size.Z)/2 return{min=cframe.Position-extents,max=cframe.Position+extents}end local function onWorkspaceDescendantAdded(descendant)if not isKillPlane(descendant)then return end killPlanes[descendant]=getBounds(descendant)or false end local function onWorkspaceDescendantRemoving(descendant)killPlanes[descendant]=nil end local function getKillPlaneY(position)local fpdh=workspace:GetAttribute("OriginalFPDH")or workspace.FallenPartsDestroyHeight local best=(typeof(fpdh)=="number"and fpdh==fpdh)and fpdh or nil for part,cached in next,killPlanes do local data=getBounds(part)or cached if not data then continue end killPlanes[part]=data if position.X<data.min.X or position.X>data.max.X then continue end if position.Z<data.min.Z or position.Z>data.max.Z then continue end if not best or data.max.Y>best then best=data.max.Y end end return best end local function getDepthsRoofY(position)local map=workspace:FindFirstChild("Map")if not map then return DEPTHS_ROOF_Y end local params=RaycastParams.new()params.FilterDescendantsInstances={map}params.FilterType=Enum.RaycastFilterType.Include local result=workspace:Raycast(Vector3.new(position.X,DEPTHS_ROOF_Y,position.Z),Vector3.new(0,-DEPTHS_RAY_LENGTH,0),params)return result and result.Position.Y+ROOF_OFFSET or DEPTHS_ROOF_Y end local function updateFakeVoid()if not Configuration.expectToggleValue("FakeVoid")then return end if os.clock()-lastTeleport<=TELEPORT_COOLDOWN then return end local character=players.LocalPlayer and players.LocalPlayer.Character local rootPart=character and character:FindFirstChild("HumanoidRootPart")if not rootPart then return end local position=rootPart.Position local killPlaneY=getKillPlaneY(position)if not killPlaneY or position.Y-killPlaneY>TRIGGER_HEIGHT then return end local targetY=getDepthsRoofY(position)if targetY-killPlaneY<=TRIGGER_HEIGHT then return end lastTeleport=os.clock()Logger.warn("(FakeVoid) Teleporting from Y %.1f to Y %.1f (kill Y %.1f).",position.Y,targetY,killPlaneY)rootPart.CFrame=rootPart.CFrame+Vector3.new(0,targetY-position.Y,0)rootPart.AssemblyLinearVelocity=rootPart.AssemblyLinearVelocity*Vector3.new(1,0,1)end function FakeVoid.init()if initialized then return end initialized=true for _,descendant in next,workspace:GetDescendants()do onWorkspaceDescendantAdded(descendant)end fakeVoidMaid:add(workspaceDescendantAdded:connect("FakeVoid_WorkspaceDescendantAdded",onWorkspaceDescendantAdded))fakeVoidMaid:add(workspaceDescendantRemoving:connect("FakeVoid_WorkspaceDescendantRemoving",onWorkspaceDescendantRemoving))fakeVoidMaid:add(preSimulation:connect("FakeVoid_PreSimulation",updateFakeVoid))if not LPH_OBFUSCATED or shared.Aero.verbose then local count=0 for _ in next,killPlanes do count=count+1 end Logger.warn("FakeVoid initialized with %d kill planes.",count)end end function FakeVoid.detach()if not initialized then return end initialized=false fakeVoidMaid:clean()table.clear(killPlanes)if not LPH_OBFUSCATED or(shared.Aero and shared.Aero.verbose)then Logger.warn("FakeVoid detached.")end end return FakeVoid end)__bundle_register("Menu/AeroTab",function(require,_LOADED,__bundle_register,__bundle_modules)local AeroTab={}local Icons=require("GUI/Icons")local ThemeManager=require("GUI/ThemeManager")local SaveManager=require("GUI/SaveManager")local Library=require("GUI/Library")local Logger=require("Utility/Logger")local SpotifyClient=require("Utility/SpotifyClient")local SpotifyWidget=require("GUI/SpotifyWidget")function AeroTab.initCheatSettingsSection(groupbox)groupbox:AddButton("Toggle Silent Mode",function()if not isfile or not delfile or not writefile then return end shared.Aero.silent=not shared.Aero.silent if not shared.Aero.silent then Logger.notify("Silent mode was disabled.")end if isfile("smarker.txt")then delfile("smarker.txt")else writefile("smarker.txt","Hello, if you're reading this, that means you have Aero (Deepwoken) silent mode turned on. Deleting this file will turn it off.")end end)groupbox:AddButton("Toggle Player Scanning",function()if not isfile or not delfile or not writefile then return end shared.Aero.dpscanning=not shared.Aero.dpscanning if shared.Aero.dpscanning then Logger.notify("Player scanning was disabled.")else Logger.notify("Player scanning was enabled.")end if isfile("dpscanning.txt")then delfile("dpscanning.txt")else writefile("dpscanning.txt","Hello, if you're reading this, that means you have Aero (Deepwoken) player scanning turned off. Deleting this file will turn it on.")end end)groupbox:AddButton("Toggle Bloxstrap RPC",function()if not isfile or not delfile or not writefile then return end shared.Aero.norpc=not shared.Aero.norpc if not shared.Aero.norpc then Logger.notify("Bloxstrap RPC was enabled.")else Logger.notify("Bloxstrap RPC was disabled.")end if isfile("norpc.txt")then delfile("norpc.txt")else writefile("norpc.txt","Hello, if you're reading this, that means you have Aero (Deepwoken) Bloxstrap RPC turned off. Deleting this file will turn it on.")end end)groupbox:AddButton("Toggle Debug Logs",function()if not isfile or not delfile or not writefile then return end shared.Aero.verbose=not shared.Aero.verbose if shared.Aero.verbose then Logger.notify("Debug logs were enabled.")else Logger.notify("Debug logs were disabled.")end if isfile("verbose.txt")then delfile("verbose.txt")else writefile("verbose.txt","Hello, if you're reading this, that means you have Aero (Deepwoken) debug logs turned on. Deleting this file will turn it off.")end end)groupbox:AddButton("Unload Cheat",function()shared.Aero.detach()end)end function AeroTab.initSpotifySection(groupbox)groupbox:AddButton("Copy Auth URL",function()setclipboard(SpotifyClient.getAuthUrl())Logger.notify("Auth URL copied. Open it in a browser, log in, click Allow, then copy the URL it redirects to (even if the page fails to load).")end)local redirectUrlInput=groupbox:AddInput("SpotifyRedirectUrl",{Text="Redirect URL",Placeholder="Paste the full URL you were redirected to here.",})groupbox:AddButton("Authorize",function()local ok,err=SpotifyClient.completeAuth(redirectUrlInput.Value)if ok then Logger.notify("Spotify authorized successfully.")else Logger.notify("Spotify authorization failed: "..tostring(err))end end)SpotifyWidget.init(Library)local showWidgetToggle=groupbox:AddToggle("ShowSpotifyWidget",{Text="Show Spotify Widget",Default=false,})showWidgetToggle:OnChanged(function(state)SpotifyWidget.setVisible(state)end)end function AeroTab.initUISettingsSection(groupbox)groupbox:AddSlider("NotificationScale",{Text="Notification Scale",Min=50,Max=300,Default=100,Rounding=0,Suffix="%",})groupbox:AddSlider("QuickNotificationSpeed",{Text="Quick Notification Speed",Min=0.1,Max=2.0,Default=0.5,Rounding=2,Suffix="s",})local menuBindLabel=groupbox:AddLabel("Menu Bind")menuBindLabel:AddKeyPicker("MenuKeybind",{Default="LeftAlt",NoUI=true,Text="Menu Keybind"})local keybindFrameLabel=groupbox:AddLabel("Keybind List Bind")keybindFrameLabel:AddKeyPicker("KeybindList",{Default="N/A",Mode="Off",NoUI=true,Text="Keybind List",Callback=function(Value)Library.KeybindFrame.Visible=Value end,})local onlyEnabledKeybinds=groupbox:AddToggle("OnlyShowEnabledKeybinds",{Text="Only Show Enabled Keybinds",Tooltip="Hide keybinds from the on-screen list unless their feature is currently toggled on.",Default=false,})onlyEnabledKeybinds:OnChanged(function()for _,option in pairs(Options)do if option.Type=="KeyPicker"and option.Update then option:Update()end end end)local watermarkFrameLabel=groupbox:AddLabel("Watermark Bind")watermarkFrameLabel:AddKeyPicker("Watermark",{Default="N/A",Mode="Off",NoUI=true,Text="Watermark",Callback=function(Value)Library:SetWatermarkVisibility(Value)end,})groupbox:AddToggle("HideUIInMenus",{Text="Hide UI In Menus",Tooltip="Hide the keybind list and watermark while the inventory or other in-game menus are open.",Default=false,})local arrayListToggle=groupbox:AddToggle("YSL_ArrayListEnabled",{Text="Array List",Tooltip="Show currently enabled toggles in a movable on-screen list.",Default=false,ArrayList=false,})arrayListToggle:OnChanged(function(enabled)if Library.ArrayListController then Library.ArrayListController:SetVisible(enabled)end end)local arrayListBackgroundToggle=groupbox:AddToggle("YSL_ArrayListBackground",{Text="Array List Background",Tooltip="Draw a translucent background behind each ArrayList row.",Default=true,ArrayList=false,})arrayListBackgroundToggle:OnChanged(function(enabled)if Library.ArrayListController then Library.ArrayListController:SetBackgroundEnabled(enabled)end end)end function AeroTab.init(window)local tab=window:AddTab("Settings","Settings",Icons.Settings)local tabbox=tab:AddFullTabbox()AeroTab.initCheatSettingsSection(tabbox:AddTab("Cheat"))AeroTab.initUISettingsSection(tabbox:AddTab("Interface"))local debugTab=tabbox:AddTab("Debug")local CombatTab=require("Menu/CombatTab")local GameTab=require("Menu/GameTab")local AutomationTab=require("Menu/AutomationTab")if not LRM_UserNote then CombatTab.initDebuggingSection(debugTab)end GameTab.initDebuggingSection(debugTab)if not LRM_UserNote then AutomationTab.initDebuggingSection(debugTab)end ThemeManager:ApplyToGroupbox(tabbox:AddTab("Theme"))if not LPH_OBFUSCATED then AeroTab.initSpotifySection(tabbox:AddTab("Spotify"))end end return AeroTab end)__bundle_register("Menu/AutomationTab",function(require,_LOADED,__bundle_register,__bundle_modules)local AutomationTab={}local Icons=require("GUI/Icons")local Logger=require("Utility/Logger")local QueuedBlocking=require("G