ock")if not unblockRemote then return end unblockRemote:FireServer()end)groupbox:AddButton("Test Tween",function()local positions={CFrame.new(2414.70,442.28,-5595.58),CFrame.new(2424.78,408.30,-5501.38),CFrame.new(2429.86,408.30,-5495.80),CFrame.new(2507.99,414.60,-5560.85),CFrame.new(600.33,983.29,-7643.66),CFrame.new(669.22,979.31,-7668.61),CFrame.new(2960.38,404.16,-5604.14),}for idx,position in next,positions do Tweening.goal(string.format("TweenToTest_%i",idx),position,true)end end)groupbox:AddButton("Cancel Tween",function()for idx=1,7 do Tweening.stop(string.format("TweenToTest_%i",idx))end end)end function AutomationTab.initAutoFerrymanSection(groupbox)groupbox:AddButton({Text="Start",DoubleClick=true,Func=function()AutoFerryman.start()end,})addAutoLogSlider(groupbox,"FerrymanAutoLogDist","auto_ferryman")addTweenSpeedSlider(groupbox,"FerrymanTweenSpeed")end function AutomationTab.initAutoTo1Section(groupbox)groupbox:AddButton({Text="Start",DoubleClick=true,Func=function()AutoTo1.start()end,})addTweenSpeedSlider(groupbox,"To1TweenSpeed")end function AutomationTab.initAutoVoISection(groupbox)groupbox:AddButton({Text="Start Shogun",DoubleClick=true,Func=function()AutoVoI.start("shogun")end,})groupbox:AddButton({Text="Start Rat King",DoubleClick=true,Func=function()AutoVoI.start("ratking")end,})addTweenSpeedSlider(groupbox,"VoITweenSpeed")end function AutomationTab.initAutoLootSection(groupbox)groupbox:AddToggle("AutoLoot",{Text="Auto Loot",Tooltip="Automatically loot items from choice prompts with filtering options.",Default=false,}):AddKeyPicker("AutoLootKeybind",{Default="N/A",SyncToggleState=true,Text="Auto Loot",})local autoLootDepBox=groupbox:AddDependencyBox()autoLootDepBox:AddToggle("AutoLootAll",{Text="Loot All Items",Tooltip="Loot all items from choice prompts. This will ignore filtering options.",Default=false,})local autoLootAllDepBox=autoLootDepBox:AddDependencyBox()autoLootAllDepBox:AddSlider("AutoLootStarsMin",{Text="Minimum Stars",Tooltip="The mi