	for _, when in ipairs(hits) do
		local action = Action.new()
		action._type = "Parry"
		action._when = when
		action.hitbox = Vector3.new(25, 25, 30)
		action.name = string.format("Multi-Hit @ %dms", when)
		self:action(timing, action)
	end
end
