	local action = Action.new()
	action._type = "Parry"
	action._when = (750 * 1.21) / speed
	action.hitbox = Vector3.new(80, 250, 140)
	action.name = string.format("(%.2fx) Speed Scaled Timing", speed)

	return self:action(timing, action)
end
