		action._when = 0
		action.ihbc = true
		action.name = "Close Sub-Timing"
		return self:action(closeTiming, action)
	end

	local action = Action.new()
	action._type = "Parry"
	action._when = 300
	action.hitbox = Vector3.new(15, 15, 30)
	action.name = "Far Timing"
	return self:action(timing, action)
end
